/* GERADO por scripts/dividir-dados.js — não edite à mão.
   A fonte editável continua sendo js/data*.js. */
registrarDetalhes({"CT-001":{"cognitivo":{"motivo":"Base de toda a contabilidade — item 2 do edital.","palavraCritica":"A = P + PL ⇔ PL = A − P"},"comentario":{"resolucao":"CERTO. Equação fundamental: ATIVO = PASSIVO + PATRIMÔNIO LÍQUIDO. Daí a situação líquida (PL) = Ativo − Passivo exigível. PL positivo: ativo supera obrigações; PL negativo (passivo a descoberto): dívidas superam bens e direitos.","fundamento":"Teoria contábil — estática patrimonial.","macete":"Balanço 'fecha' sempre: os dois lados pesam igual por definição.","erroComum":"Inverter os termos da diferença na situação líquida.","comoBancaPensa":"Fórmula de três termos = três pontos de troca possíveis; conferir cada termo é obrigatório."}},"CT-002":{"cognitivo":{"motivo":"Classificação dos fatos contábeis — item 3 do edital.","palavraCritica":"não altera o PL"},"comentario":{"resolucao":"ERRADO. Trata-se de fato PERMUTATIVO (ou qualitativo): troca de um ativo (caixa) por outro (veículo) de igual valor, alterando a composição do patrimônio sem modificar o total do PL. Modificativos envolvem receitas ou despesas (ex.: pagamento de salários); mistos combinam permuta e modificação (ex.: venda de mercadoria com lucro).","fundamento":"Teoria contábil — classificação dos fatos administrativos.","macete":"Se não passou por receita/despesa, o PL nem percebeu.","erroComum":"Confundir saída de caixa com redução de riqueza própria.","comoBancaPensa":"Classificação tripartite = rotação constante de exemplos com rótulo trocado."}},"CT-003":{"cognitivo":{"motivo":"Desfazer a associação leiga débito=ruim / crédito=bom.","palavraCritica":"natureza da conta"},"comentario":{"resolucao":"ERRADO. O efeito do débito e do crédito depende da natureza da conta: nas contas de natureza devedora (ativo e despesas), o débito aumenta e o crédito diminui o saldo; nas de natureza credora (passivo, patrimônio líquido e receitas), ocorre o inverso. Não há 'sempre'.","fundamento":"Método das partidas dobradas — natureza e funcionamento das contas.","macete":"Comprar caixa (ativo) se faz DEBITANDO caixa — débito aumentando saldo.","erroComum":"Importar a semântica do extrato bancário para a escrituração.","comoBancaPensa":"'Sempre' + regra que comporta duas famílias de contas = item errado sob medida."}},"CT-004":{"cognitivo":{"motivo":"Limite técnico do balancete — pega quem o toma por auditoria.","palavraCritica":"necessária ≠ suficiente"},"comentario":{"resolucao":"ERRADO. A igualdade débitos = créditos é consequência automática das partidas dobradas e revela apenas equilíbrio aritmético. Persistem invisíveis ao balancete: omissão integral de lançamento, duplicidade, inversão de contas, classificação incorreta e erros de igual valor em ambos os lados.","fundamento":"Técnica contábil — balancete de verificação (limitações).","macete":"Fechar as somas ≠ contar a verdade: fraude bem lançada também 'bate'.","erroComum":"Tratar o balancete como prova de exatidão da escrituração.","comoBancaPensa":"Para carreira policial, o detalhe é investigativo: livros equilibrados podem esconder fraude."}},"CT-005":{"cognitivo":{"motivo":"Tipologia expressamente citada no edital (item 9 de Análise Financeira).","palavraCritica":"abaixo do limiar de comunicação"},"comentario":{"resolucao":"CERTO. Smurfing (ou structuring) é o fracionamento deliberado de valores em operações menores, distribuídas em datas, contas ou agências distintas, para escapar dos limiares de comunicação automática ao COAF (Lei 9.613/1998; Circular Bacen 3.978/2020). Integra a fase de colocação da lavagem.","fundamento":"Lei 9.613/1998; tipologias GAFI/COAF.","macete":"Depósitos 'redondos', repetidos e logo abaixo do limite = alerta máximo.","erroComum":"Confundir com a mera utilização de interpostas pessoas (laranjas).","comoBancaPensa":"Termo técnico do edital novo = definição literal cobrada nas primeiras provas."}},"CT-006":{"cognitivo":{"motivo":"Red flags dos itens 7-13 do edital + valor probatório do indício.","palavraCritica":"orientar a investigação"},"comentario":{"resolucao":"CERTO. Movimentações incompatíveis com a renda e a interposição de terceiros são tipologias clássicas de ocultação patrimonial (Lei 9.613/1998) e fundamentam relatórios de inteligência financeira e medidas investigativas. Contudo, a condenação exige o standard probatório do processo penal — indícios isolados não bastam.","fundamento":"Lei 9.613/1998; tipologias COAF/GAFI; CPP, art. 239 (conceito de indício).","macete":"Vida de rico com renda de pobre: o papel do investigador é seguir o dinheiro (follow the money).","erroComum":"Tratar red flags como prova cabal — ou, no extremo oposto, como irrelevantes.","comoBancaPensa":"Item longo e tecnicamente equilibrado — treina a imunidade ao 'item extenso parece errado'."}},"CT-007":{"cognitivo":{"motivo":"Distinguir fatos permutativos, modificativos e mistos.","palavraCritica":"permutativo NÃO altera PL; modificativo altera"},"comentario":{"resolucao":"ERRADO. As definições estão trocadas. O fato PERMUTATIVO apenas permuta elementos patrimoniais SEM alterar o patrimônio líquido (ex.: compra de bem à vista). O fato MODIFICATIVO altera a situação líquida (ex.: pagamento de despesa, recebimento de receita). O misto combina os dois efeitos.","fundamento":"Contabilidade geral — fatos contábeis.","macete":"Permutativo = permuta (PL não muda). Modificativo = modifica o PL.","erroComum":"Inverter qual fato altera o patrimônio líquido.","comoBancaPensa":"Par conceitual espelhado (permutativo × modificativo) invertido."}},"CT-008":{"cognitivo":{"motivo":"Cobrar a estrutura do balanço e a equação patrimonial.","palavraCritica":"PL = Ativo − Passivo"},"comentario":{"resolucao":"CERTO. O balanço patrimonial reflete a equação fundamental: Ativo = Passivo + Patrimônio Líquido. O ativo (bens e direitos) fica à esquerda; o passivo (obrigações) e o PL (situação líquida = A − P) à direita. O PL é a riqueza própria da entidade.","fundamento":"Contabilidade geral — balanço patrimonial e equação patrimonial.","macete":"A = P + PL. Se A > P, situação líquida positiva (PL positivo).","erroComum":"Trocar a natureza de passivo (obrigação) por bens/direitos.","comoBancaPensa":"A composição do balanço é cobrada invertendo o que é ativo/passivo/PL."}},"CT-009":{"cognitivo":{"motivo":"Distinguir a DRE (dinâmica, resultado) do balanço (estático, posição).","palavraCritica":"posição estática = balanço (não DRE)"},"comentario":{"resolucao":"ERRADO. A descrição corresponde ao BALANÇO PATRIMONIAL (posição estática numa data). A DRE é dinâmica: confronta receitas e despesas do período para apurar o resultado (lucro ou prejuízo) do exercício.","fundamento":"Contabilidade geral — DRE × balanço patrimonial.","macete":"DRE = resultado do período (filme). Balanço = posição na data (foto).","erroComum":"Trocar a função da DRE pela do balanço.","comoBancaPensa":"Par espelhado (DRE × balanço) invertido na assertiva."}},"CT-010":{"cognitivo":{"motivo":"Distinguir contas patrimoniais das contas de resultado.","palavraCritica":"receita e despesa = contas de resultado"},"comentario":{"resolucao":"ERRADO. Receitas e despesas são contas de RESULTADO, que compõem a DRE e, após a apuração, transferem o resultado ao patrimônio líquido. As contas patrimoniais são as de ativo, passivo e PL, que integram o balanço.","fundamento":"Contabilidade geral — plano de contas.","macete":"Receita/despesa = resultado (DRE). Ativo/passivo/PL = patrimonial (balanço).","erroComum":"Classificar receita e despesa como patrimoniais.","comoBancaPensa":"Classificação de contas é cobrada trocando patrimonial × resultado."}},"CT-011":{"cognitivo":{"motivo":"Cobrar o cálculo e a interpretação da liquidez corrente.","palavraCritica":"AC ÷ PC > 1 = boa liquidez de curto prazo"},"comentario":{"resolucao":"CERTO. Liquidez Corrente = Ativo Circulante ÷ Passivo Circulante. Índice maior que 1 indica que, para cada unidade de obrigação de curto prazo, há mais de uma unidade de recursos de curto prazo — capacidade de honrar dívidas de curto prazo.","fundamento":"Análise das demonstrações contábeis — índices de liquidez.","macete":"LC = AC/PC. > 1 bom, = 1 no limite, < 1 aperto de caixa.","erroComum":"Inverter a fórmula (PC/AC) ou a leitura do resultado.","comoBancaPensa":"Fórmula de índice financeiro é cobrada invertendo numerador/denominador."}},"CT-012":{"cognitivo":{"motivo":"Cobrar o princípio das partidas dobradas.","palavraCritica":"não há necessariamente (falso)"},"comentario":{"resolucao":"ERRADO. No método das partidas dobradas (Luca Pacioli), para cada débito há sempre um crédito de igual valor — 'não há débito sem crédito correspondente'. Por isso, no balancete, a soma dos débitos é igual à soma dos créditos.","fundamento":"Contabilidade geral — método das partidas dobradas.","macete":"Débito = Crédito, sempre. Se não bate, há erro de escrituração.","erroComum":"Negar a igualdade obrigatória débito/crédito.","comoBancaPensa":"Nega o princípio-base da escrituração contábil."}},"CT-013":{"cognitivo":{"motivo":"Reconhecer tipologias de lavagem listadas nominalmente no edital.","palavraCritica":"fracionamento para evitar detecção"},"comentario":{"resolucao":"CERTO. O fracionamento intencional de valores para permanecer abaixo do limite de comunicação obrigatória é a tipologia denominada SMURFING (ou structuring). O uso de contas de pessoas sem lastro econômico caracteriza a utilização de “laranjas” (interpostas pessoas) — ambas expressamente listadas no programa do certame.","fundamento":"Lei 9.613/1998; normas do COAF; tipologias de lavagem.","macete":"Vários depósitos 'quase no limite' = smurfing. Conta de terceiro sem renda = laranja.","erroComum":"Não identificar o nome técnico da tipologia.","comoBancaPensa":"Aplica tipologias do edital a um cenário investigativo concreto."}},"CT-014":{"cognitivo":{"motivo":"Cobrar a ordem e o conteúdo das fases da lavagem.","palavraCritica":"integração (deveria ser colocação)"},"comentario":{"resolucao":"ERRADO. Há dois erros. Primeiro, o depósito em espécie corresponde à fase de COLOCAÇÃO (placement), em que os valores ingressam no sistema financeiro. Segundo, a ordem correta das fases é colocação → ocultação (layering) → integração, e não a apresentada.","fundamento":"Doutrina sobre lavagem de dinheiro (modelo trifásico do GAFI); Lei 9.613/1998.","macete":"C-O-I: Coloca, Oculta, Integra. Depósito em espécie está no começo.","erroComum":"Inverter a ordem das fases ou trocar colocação por integração.","comoBancaPensa":"Inverte a sequência de um processo em etapas — pegadinha clássica."}},"CT-015":{"cognitivo":{"motivo":"Cobrar a natureza estática do balanço patrimonial e sua composição básica.","palavraCritica":"em determinada data"},"comentario":{"resolucao":"CERTO. O balanço patrimonial é demonstração contábil estática, que evidencia a posição patrimonial e financeira da entidade em determinada data, estruturada em três grandes grupos: ativo, passivo e patrimônio líquido.","fundamento":"Lei nº 6.404/1976 (Lei das S.A.); doutrina contábil (estrutura das demonstrações financeiras).","macete":"Balanço: retrato de UMA DATA. Ativo = Passivo + PL.","erroComum":"Confundir o balanço (estático) com demonstrações de fluxo, como a DRE.","comoBancaPensa":"Item de fixação sobre a natureza e a estrutura básica do balanço patrimonial."}},"CT-016":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a natureza estática do balanço patrimonial.","palavraCritica":"resultado ... ao longo de um período"},"comentario":{"resolucao":"ERRADO. Quem evidencia o resultado (lucro ou prejuízo) de um período é a Demonstração do Resultado do Exercício (DRE) — o balanço patrimonial, por sua vez, evidencia a posição patrimonial e financeira da entidade em determinada data, e não um fluxo ao longo de um período.","fundamento":"Lei nº 6.404/1976; doutrina contábil (estrutura das demonstrações financeiras).","macete":"Resultado do período = função da DRE, não do balanço.","erroComum":"Atribuir ao balanço patrimonial uma função que é típica da DRE.","comoBancaPensa":"Troca as funções de duas demonstrações contábeis distintas, testando a precisão conceitual."}},"CT-017":{"cognitivo":{"motivo":"Cobrar que a incompatibilidade financeira é indício, não prova conclusiva isolada.","palavraCritica":"apenas indício ... insuficiente, por si só"},"comentario":{"resolucao":"CERTO. A incompatibilidade entre os fluxos financeiros de uma pessoa e sua capacidade econômica declarada é um indício relevante para a investigação, mas não constitui, isoladamente, prova conclusiva de fraude contábil ou de crime contra a ordem tributária — é necessária a análise conjunta de outros elementos probatórios.","fundamento":"Doutrina de análise financeira e contábil aplicada à investigação (indícios de lavagem/fraude).","macete":"Incompatibilidade patrimonial = indício, não prova conclusiva isolada.","erroComum":"Tratar a incompatibilidade patrimonial como prova suficiente, por si só, de ilícito.","comoBancaPensa":"Item de fixação sobre o valor probatório relativo dos indícios financeiros."}},"CT-018":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a incompatibilidade financeira é apenas indício, não prova conclusiva.","palavraCritica":"suficiente, por si só ... dispensando-se"},"comentario":{"resolucao":"ERRADO. A incompatibilidade entre os fluxos financeiros e a capacidade econômica declarada é apenas um indício relevante, mas não é suficiente, por si só, para comprovar fraude contábil ou crime contra a ordem tributária — exige-se sempre a análise conjunta de outros elementos probatórios.","fundamento":"Doutrina de análise financeira e contábil aplicada à investigação.","macete":"Nenhum indício isolado basta sozinho — sempre é necessário o conjunto probatório.","erroComum":"Tratar um único indício, ainda que relevante, como prova conclusiva e autossuficiente.","comoBancaPensa":"Generaliza indevidamente o valor probatório de um indício isolado."}},"CT-019":{"cognitivo":{"motivo":"Cobrar a importância da etapa de identificação na gestão de riscos financeiros.","palavraCritica":"etapa essencial"},"comentario":{"resolucao":"CERTO. A identificação de riscos financeiros é etapa essencial e inicial do processo de gestão de riscos, permitindo à entidade reconhecer eventos internos ou externos capazes de afetar negativamente o alcance de seus objetivos financeiros, antes de avaliá-los e tratá-los.","fundamento":"Doutrina de gestão de riscos financeiros e controles internos.","macete":"Sem identificar o risco, não há como avaliar nem tratar — é a etapa inicial e essencial.","erroComum":"Considerar a identificação como etapa dispensável ou meramente formal.","comoBancaPensa":"Item de fixação sobre o papel central da identificação no ciclo de gestão de riscos."}},"CT-020":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a identificação de riscos é etapa indispensável.","palavraCritica":"dispensa ... bastando"},"comentario":{"resolucao":"ERRADO. A identificação de riscos é etapa essencial e contínua da gestão de riscos financeiros, não podendo ser dispensada — o monitoramento de indicadores já conhecidos não substitui a necessidade de identificar novos riscos e eventos emergentes que possam afetar os objetivos da entidade.","fundamento":"Doutrina de gestão de riscos financeiros e controles internos.","macete":"Identificação de riscos: sempre necessária e contínua, nunca dispensável.","erroComum":"Achar que o monitoramento de indicadores conhecidos substitui a identificação de novos riscos.","comoBancaPensa":"Generaliza indevidamente que uma etapa avançada do processo (monitoramento) dispensa a etapa inicial (identificação)."}},"CT-021":{"cognitivo":{"motivo":"Cobrar a distinção entre a DRE (fluxo de um período) e o balanço patrimonial (posição em uma data).","palavraCritica":"ao longo de um período ... data específica"},"comentario":{"resolucao":"CERTO. A DRE é demonstração de natureza dinâmica, que apura receitas, custos, despesas e o resultado (lucro ou prejuízo) ao longo de um período, diferindo do balanço patrimonial, de natureza estática, que evidencia a posição patrimonial da entidade em uma data específica.","fundamento":"Lei nº 6.404/1976; doutrina contábil (estrutura das demonstrações financeiras).","macete":"DRE = período (fluxo). Balanço = data (posição).","erroComum":"Inverter as naturezas das duas demonstrações contábeis.","comoBancaPensa":"Item de fixação sobre a distinção estrutural entre as duas principais demonstrações contábeis."}},"CT-022":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que a DRE apura resultado de um período, e não posição em uma data.","palavraCritica":"data específica ... e não o resultado"},"comentario":{"resolucao":"ERRADO. A DRE é elaborada para apurar o resultado (receitas, custos, despesas e lucro/prejuízo) ao longo de um PERÍODO, e não para retratar a posição patrimonial em uma data específica — essa última função é do balanço patrimonial, e não da DRE.","fundamento":"Lei nº 6.404/1976; doutrina contábil (estrutura das demonstrações financeiras).","macete":"DRE: sempre um período (fluxo), nunca uma data isolada.","erroComum":"Atribuir à DRE a natureza estática que é, na verdade, do balanço patrimonial.","comoBancaPensa":"Troca as naturezas de duas demonstrações contábeis distintas."}},"CT-023":{"cognitivo":{"motivo":"Cobrar a distinção entre análise vertical e análise horizontal de demonstrações contábeis.","palavraCritica":"vertical ... participação percentual. Horizontal ... evolução"},"comentario":{"resolucao":"CERTO. A análise vertical evidencia a participação percentual de cada conta em relação a um valor-base dentro de um mesmo período, enquanto a análise horizontal evidencia a evolução de cada conta ao longo de diferentes períodos, permitindo identificar tendências de crescimento ou retração.","fundamento":"Doutrina contábil — técnicas de análise de demonstrações financeiras (análise vertical e horizontal).","macete":"Vertical = % de participação (mesma data). Horizontal = evolução no tempo.","erroComum":"Inverter as definições de análise vertical e horizontal.","comoBancaPensa":"Item de fixação sobre a distinção clássica entre as duas técnicas de análise."}},"CT-024":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a distinção entre análise vertical e horizontal.","palavraCritica":"horizontal ... participação percentual"},"comentario":{"resolucao":"ERRADO. Os conceitos foram invertidos: é a análise VERTICAL (e não a horizontal) que evidencia a participação percentual de cada conta em relação a um valor-base dentro de um mesmo período; é a análise HORIZONTAL (e não a vertical) que evidencia a evolução das contas ao longo de diferentes períodos.","fundamento":"Doutrina contábil — técnicas de análise de demonstrações financeiras.","macete":"Vertical = % (mesma data). Horizontal = evolução (vários períodos).","erroComum":"Não perceber a inversão proposital entre os dois conceitos.","comoBancaPensa":"Testa a mesma distinção clássica, mas com os termos deliberadamente trocados."}},"CT-025":{"cognitivo":{"motivo":"Cobrar a fórmula e a interpretação do índice de liquidez corrente.","palavraCritica":"ativo circulante / passivo circulante"},"comentario":{"resolucao":"CERTO. LC = Ativo Circulante ÷ Passivo Circulante; acima de 1, há mais direitos de curto prazo do que obrigações de curto prazo. O que salva o item é o \"em tese\", e é aí que mora a lição: o índice não distingue estoque encalhado de dinheiro em caixa, nem casa os PRAZOS — a duplicata pode vencer depois da obrigação que deveria pagar. Por isso liquidez corrente alta não é sinônimo de solvência, e por isso existe a liquidez seca, que expurga os estoques justamente para corrigir essa cegueira. Item que dissesse que LC > 1 \"assegura\" o pagamento estaria ERRADO.","fundamento":"Doutrina contábil — análise de índices financeiros (liquidez).","macete":"Liquidez corrente = AC / PC. Sempre ativo dividido por passivo, nunca o inverso.","erroComum":"Inverter a fórmula, dividindo o passivo circulante pelo ativo circulante.","comoBancaPensa":"Item de fixação sobre um dos índices financeiros mais cobrados em provas."}},"CT-026":{"cognitivo":{"motivo":"Cobrar, na forma invertida, a fórmula correta do índice de liquidez corrente.","palavraCritica":"passivo circulante pelo ativo circulante"},"comentario":{"resolucao":"ERRADO. A fórmula correta do índice de liquidez corrente é Ativo Circulante / Passivo Circulante, e não o inverso. Ademais, se o cálculo fosse feito na forma invertida proposta pelo item, um resultado superior a 1 indicaria, na verdade, situação financeira desfavorável (mais obrigações do que recursos de curto prazo).","fundamento":"Doutrina contábil — análise de índices financeiros (liquidez).","macete":"Liquidez corrente = AC / PC. Nunca inverta a fórmula.","erroComum":"Inverter numerador e denominador, distorcendo completamente a interpretação do índice.","comoBancaPensa":"Inverte a fórmula de um índice clássico para testar a memorização correta do candidato."}},"CT-027":{"cognitivo":{"motivo":"Cobrar a distinção entre regime de competência (regra geral contábil) e regime de caixa.","palavraCritica":"regime de competência ... independentemente do efetivo recebimento ou pagamento"},"comentario":{"resolucao":"CERTO. Competência olha o fato gerador; caixa olha a movimentação do dinheiro. Venda a prazo fechada em dezembro e recebida em março é receita de DEZEMBRO. É essa separação que dá sentido a contas como despesa antecipada e receita a receber — elas existem para acomodar a distância entre o fato e o pagamento. Cuidado com a extensão indevida: o setor público brasileiro adota regime MISTO na execução orçamentária (Lei 4.320/1964, art. 35 — receita pelo caixa, despesa pela competência). O enunciado se salva ao delimitar \"contabilidade societária\".","fundamento":"Doutrina contábil — princípios de contabilidade (regime de competência).","macete":"Competência = regra geral. Reconhece pelo FATO, não pelo dinheiro entrando/saindo.","erroComum":"Achar que o regime de caixa é a regra geral da contabilidade societária.","comoBancaPensa":"Item de fixação sobre um dos princípios contábeis mais fundamentais."}},"CT-028":{"cognitivo":{"motivo":"Cobrar, na forma invertida, que o regime de competência (e não o de caixa) é a regra geral contábil.","palavraCritica":"regime de caixa ... regra geral"},"comentario":{"resolucao":"ERRADO. A regra geral da contabilidade societária brasileira é o regime de COMPETÊNCIA (e não o de caixa): receitas e despesas são reconhecidas no período em que ocorrem, independentemente do efetivo recebimento ou pagamento em dinheiro.","fundamento":"Doutrina contábil — princípios de contabilidade (regime de competência).","macete":"Regra geral = competência. Regime de caixa é exceção em contextos específicos.","erroComum":"Inverter os dois regimes, tratando o de caixa como a regra geral contábil.","comoBancaPensa":"Troca os dois regimes entre si, testando a memorização da regra geral correta."}},"CT-029":{"cognitivo":{"motivo":"Fixar o regime contábil misto adotado pela Lei 4.320.","palavraCritica":"efetivamente pagas"},"comentario":{"resolucao":"ERRADO. Pertencem ao exercício financeiro as receitas nele arrecadadas e as despesas nele LEGALMENTE EMPENHADAS. É o chamado regime misto: caixa para as receitas e competência para as despesas. Despesa empenhada e não paga ao fim do exercício é inscrita em restos a pagar.","fundamento":"Lei 4.320/1964, art. 35, I e II.","macete":"Arrecadadas e empenhadas — regime misto.","erroComum":"Vincular a despesa ao exercício pelo pagamento.","comoBancaPensa":"Acerta o inciso I e altera o inciso II, aproveitando a simetria da frase para induzir leitura apressada."}},"CT-030":{"cognitivo":{"motivo":"Distinguir empenho de liquidação nos estágios da despesa pública.","palavraCritica":"O empenho ... verificação do direito adquirido"},"comentario":{"resolucao":"ERRADO. A definição apresentada é a de LIQUIDAÇÃO da despesa. O empenho é o ato emanado de autoridade competente que cria para o Estado obrigação de pagamento pendente ou não de implemento de condição, e antecede a liquidação na ordem dos estágios.","fundamento":"Lei 4.320/1964, art. 58 (empenho) e art. 63 (liquidação).","macete":"Empenho cria a obrigação; liquidação verifica o direito.","erroComum":"Trocar as definições de empenho e liquidação.","comoBancaPensa":"Transcreve com fidelidade a definição de um instituto e a atribui ao instituto vizinho."}},"CT-031":{"cognitivo":{"motivo":"Delimitar a classificação econômica da receita orçamentária.","palavraCritica":"operações de crédito"},"comentario":{"resolucao":"ERRADO. As receitas provenientes de operações de crédito são receitas de CAPITAL, por resultarem da constituição de dívidas. As demais categorias listadas — tributária, de contribuições, patrimonial, agropecuária, industrial e de serviços — são efetivamente receitas correntes.","fundamento":"Lei 4.320/1964, art. 11, §§1º e 2º.","macete":"Constituiu dívida, é receita de capital.","erroComum":"Classificar empréstimo como receita corrente por ingressar no caixa.","comoBancaPensa":"Reproduz o rol legal e anexa um item da categoria vizinha."}},"CT-032":{"cognitivo":{"motivo":"Fixar qual estágio da despesa é pressuposto de sua realização.","palavraCritica":"liquidação"},"comentario":{"resolucao":"ERRADO. A vedação legal é à realização de despesa sem prévio EMPENHO. A liquidação é estágio posterior ao empenho, de modo que exigi-la previamente inverteria a sequência legal dos estágios da despesa pública.","fundamento":"Lei 4.320/1964, art. 60.","macete":"Sem empenho prévio não há despesa.","erroComum":"Trocar empenho por liquidação.","comoBancaPensa":"Em frase curta, a troca de uma única palavra é mais difícil de perceber do que em texto longo."}},"CT-033":{"cognitivo":{"motivo":"Fixar a definição de liquidação no lugar certo.","palavraCritica":"liquidação ... verificação"},"comentario":{"resolucao":"CERTO. O art. 63 da Lei 4.320/1964 define a liquidação exatamente como a verificação do direito adquirido pelo credor com base nos títulos e documentos comprobatórios, apurando origem, objeto, valor e a quem se deve pagar.","fundamento":"Lei 4.320/1964, art. 63; art. 58.","macete":"Liquidação confere o direito do credor.","erroComum":"Atribuir a definição ao empenho.","comoBancaPensa":"Traz o par correto depois de muitas questões com a troca."}},"CT-034":{"cognitivo":{"motivo":"Fixar a classificação econômica correta da operação de crédito.","palavraCritica":"constituição de dívidas"},"comentario":{"resolucao":"CERTO. O art. 11, §2º, da Lei 4.320/1964 classifica como receitas de capital as provenientes da constituição de dívidas, o que abrange as operações de crédito. Não são receitas correntes, apesar do ingresso financeiro.","fundamento":"Lei 4.320/1964, art. 11, §§1º e 2º.","macete":"Constituiu dívida = receita de capital.","erroComum":"Classificar como corrente pelo ingresso em caixa.","comoBancaPensa":"Classificação correta acompanhada do fundamento."}},"CT-035":{"cognitivo":{"motivo":"Separar dois conceitos do plano de contas que a banca troca sistematicamente.","palavraCritica":"função"},"comentario":{"resolucao":"ERRADO. O que se descreve é o FUNCIONAMENTO da conta — a mecânica de débito e crédito que faz o saldo subir ou descer. A FUNÇÃO é outra coisa: é a finalidade da conta, o que ela se destina a registrar. A conta Fornecedores tem por função registrar as obrigações com terceiros pelo fornecimento de bens e serviços; seu funcionamento é aumentar a crédito e diminuir a débito. Um responde 'para que serve', o outro 'como se movimenta'.","fundamento":"Doutrina contábil — estrutura do plano de contas (elenco, função, funcionamento e codificação).","macete":"Função = para que serve. Funcionamento = como debita e credita.","erroComum":"Tratar os dois termos como sinônimos por aparecerem juntos na definição do plano de contas.","comoBancaPensa":"Descreve corretamente um conceito e o rotula com o nome do outro."}},"CT-036":{"cognitivo":{"motivo":"Distinguir instrumento de organização interna de livro contábil obrigatório.","palavraCritica":"livros contábeis obrigatórios"},"comentario":{"resolucao":"ERRADO. O plano de contas não é livro contábil e não se sujeita a registro ou autenticação. É instrumento de organização interna da escrituração, elaborado por cada entidade conforme suas necessidades e seu ramo de atividade. Livro obrigatório por excelência é o Diário, exigido pela legislação comercial e fiscal; o Razão é auxiliar de escrituração. O plano de contas antecede os dois: é o mapa que define quais contas serão usadas e como.","fundamento":"Doutrina contábil — livros de escrituração; Lei 6.404/1976, art. 177.","macete":"Plano de contas organiza; Diário registra. Só o segundo é livro obrigatório.","erroComum":"Presumir formalidade de registro por se tratar de documento contábil estruturado.","comoBancaPensa":"Empresta ao plano de contas a formalidade que pertence aos livros de escrituração."}},"CT-037":{"cognitivo":{"motivo":"Cobrar os componentes do plano de contas além da simples relação de contas.","palavraCritica":"esgota-se"},"comentario":{"resolucao":"ERRADO. O elenco é apenas um dos componentes. O plano de contas compreende também a FUNÇÃO de cada conta (o que registra), o seu FUNCIONAMENTO (como é debitada e creditada) e a CODIFICAÇÃO que organiza a hierarquia entre contas sintéticas e analíticas. Um plano reduzido a lista de nomes não cumpriria seu papel, que é padronizar a escrituração e permitir que pessoas diferentes classifiquem o mesmo fato da mesma forma.","fundamento":"Doutrina contábil — estrutura e finalidade do plano de contas.","macete":"Elenco + função + funcionamento + codificação. O elenco sozinho não basta.","erroComum":"Reduzir o plano de contas à relação de contas disponíveis.","comoBancaPensa":"Apresenta parte verdadeira do conceito com verbo de exclusividade."}},"CT-038":{"cognitivo":{"motivo":"Fixar a distinção por nível de detalhamento, base da codificação do plano de contas.","palavraCritica":"não recebem lançamentos diretos"},"comentario":{"resolucao":"CERTO. A conta sintética é totalizadora: seu saldo resulta da soma das contas que ela agrupa, e por isso não recebe lançamento direto. A analítica é o último nível da hierarquia e é onde a escrituração efetivamente ocorre. Exemplo: 'Disponibilidades' é sintética; 'Caixa' e 'Banco Conta Movimento' são analíticas, e é nelas que se debita e credita. Confundir os níveis leva a lançar em conta totalizadora, o que quebra a estrutura do plano.","fundamento":"Doutrina contábil — classificação das contas quanto ao nível de detalhamento.","macete":"Sintética totaliza. Analítica recebe lançamento.","erroComum":"Inverter os papéis por associar 'analítica' a análise e não a detalhe.","comoBancaPensa":"Item conceitual correto, usado como âncora antes das inversões nos itens seguintes."}},"CT-039":{"cognitivo":{"motivo":"Fixar a característica que explica a presença de saldos de ambas as naturezas no ativo e no passivo.","palavraCritica":"inversa"},"comentario":{"resolucao":"CERTO. A conta redutora — ou retificadora — existe para diminuir o saldo do grupo a que pertence, e por isso tem natureza contrária. Depreciação Acumulada é CREDORA e fica dentro do Ativo Imobilizado, reduzindo-o; Ações em Tesouraria é DEVEDORA e fica no Patrimônio Líquido, reduzindo-o. É essa mecânica que faz o ativo conter contas credoras, e não apenas devedoras — desdobramento cobrado com frequência.","fundamento":"Doutrina contábil — contas retificadoras; Lei 6.404/1976, arts. 178 a 182.","macete":"Redutora tem sempre a natureza contrária à do grupo que retifica.","erroComum":"Supor que toda conta do ativo é devedora sem exceção.","comoBancaPensa":"Conceito simples que serve de premissa para itens mais difíceis sobre natureza de saldos."}},"CT-040":{"cognitivo":{"motivo":"Cobrar a consequência das contas redutoras sobre a composição dos grupos patrimoniais.","palavraCritica":"tanto ... quanto"},"comentario":{"resolucao":"CERTO, e a explicação está nas contas redutoras. A REGRA é que o ativo tenha saldo devedor e o passivo, credor; as retificadoras rompem essa uniformidade dentro de cada grupo. No ativo, Depreciação Acumulada e Provisão para Perdas de Crédito Esperadas são credoras. No passivo, Encargos Financeiros a Transcorrer é devedora, reduzindo a obrigação. Item que afirme uniformidade absoluta de natureza dentro do grupo estaria errado.","fundamento":"Doutrina contábil — natureza dos saldos e contas retificadoras; Lei 6.404/1976, art. 178.","macete":"A regra é uniforme; as redutoras são a exceção que a banca cobra.","erroComum":"Negar por aplicar a regra geral sem lembrar das retificadoras.","comoBancaPensa":"Afirma a exceção como se fosse descrição geral, punindo quem só decorou a regra."}},"CT-041":{"cognitivo":{"motivo":"Cobrar a natureza patrimonial de uma conta cujo nome sugere resultado.","palavraCritica":"lucros ou prejuízos acumulados"},"comentario":{"resolucao":"ERRADO. Lucros ou Prejuízos Acumulados é conta PATRIMONIAL, integrante do Patrimônio Líquido, e não conta de resultado. A distinção é de ciclo de vida: contas de resultado nascem e morrem dentro do exercício — são encerradas na apuração e não migram para o balanço; a de lucros acumulados é permanente e figura no balanço patrimonial. O nome engana porque contém a palavra 'lucros', mas ela RECEBE o resultado apurado, não o compõe.","fundamento":"Lei 6.404/1976, art. 178, § 2º, III, e art. 187; doutrina contábil — encerramento das contas de resultado.","macete":"Resultado zera no fim do exercício. Lucros acumulados fica no balanço.","erroComum":"Classificar pela palavra 'lucros' presente no nome da conta.","comoBancaPensa":"Anexa uma conta patrimonial a uma afirmação verdadeira sobre contas de resultado."}},"CT-042":{"cognitivo":{"motivo":"Fixar que o grupo de resultado não tem natureza única.","palavraCritica":"conforme se trate de despesa ou de receita"},"comentario":{"resolucao":"CERTO. Despesas são devedoras e receitas são credoras — o grupo de resultado, portanto, comporta as duas naturezas, e não uma só. A lógica está no efeito sobre o patrimônio líquido: a receita o aumenta, e aumento de PL registra-se a crédito; a despesa o reduz, e redução de PL registra-se a débito. Essa mesma lógica explica por que ativo é devedor e passivo é credor, e é o que permite deduzir a natureza de qualquer conta sem decorar.","fundamento":"Doutrina contábil — método das partidas dobradas e natureza dos saldos.","macete":"Aumenta PL, credita. Reduz PL, debita. Receita e despesa seguem daí.","erroComum":"Atribuir natureza única ao grupo de resultado, como se faz com ativo e passivo.","comoBancaPensa":"Cobra a dedução da natureza a partir do efeito patrimonial."}},"CT-043":{"cognitivo":{"motivo":"Cobrar que a segregação por prazo alcança apenas parte das contas.","palavraCritica":"Todas"},"comentario":{"resolucao":"ERRADO. A segregação entre circulante e não circulante é critério de PRAZO de realização ou exigibilidade, aplicável ao ativo e ao passivo. Não alcança as contas de resultado — não existe 'receita circulante' —, nem o patrimônio líquido, nem as contas de compensação. Item que estende a classificação a todo o plano de contas generaliza um critério que a própria estrutura do balanço restringe a dois grupos.","fundamento":"Lei 6.404/1976, art. 178, §§ 1º e 2º.","macete":"Circulante/não circulante é só para ativo e passivo. Resultado e PL ficam fora.","erroComum":"Estender ao plano inteiro um critério próprio dos grupos patrimoniais.","comoBancaPensa":"Aplica a todo o universo um critério verdadeiro apenas para um subconjunto."}},"CT-044":{"cognitivo":{"motivo":"Fixar a função das contas de compensação e sua ligação com atos administrativos.","palavraCritica":"atos administrativos"},"comentario":{"resolucao":"CERTO. As contas de compensação são o registro dos ATOS administrativos — aqueles que, por si, não modificam o patrimônio, mas podem vir a modificá-lo. Aval concedido, garantia prestada, contrato de seguro firmado: nada disso altera ativo, passivo ou PL no momento em que ocorre, mas todos criam risco potencial que interessa ao usuário da informação. É a distinção clássica entre ATO e FATO administrativo: o fato altera o patrimônio, o ato não altera mas pode vir a alterar.","fundamento":"Doutrina contábil — atos e fatos administrativos; contas de compensação.","macete":"Ato pode vir a mexer no patrimônio; fato já mexeu. Compensação registra o ato.","erroComum":"Confundir contas de compensação com contas retificadoras.","comoBancaPensa":"Cobra a ponte entre a teoria dos atos administrativos e a estrutura de contas."}},"CT-045":{"cognitivo":{"motivo":"Cobrar a direção correta do lançamento em fato permutativo, com justificativa enganosa.","palavraCritica":"há saída de dinheiro e entrada de um bem"},"comentario":{"resolucao":"ERRADO. O lançamento está invertido: debita-se IMÓVEIS e credita-se BANCOS. A justificativa oferecida pelo item é verdadeira nos fatos — dinheiro sai, bem entra — mas conduz à conclusão contrária, porque no ativo o aumento se registra a DÉBITO e a redução a CRÉDITO. Imóveis aumentou, logo é debitada; Bancos diminuiu, logo é creditada. Trata-se de fato permutativo: troca-se um elemento do ativo por outro, sem alterar o patrimônio líquido.","fundamento":"Doutrina contábil — método das partidas dobradas; fatos permutativos.","macete":"No ativo: aumentou, debita. Diminuiu, credita.","erroComum":"Associar 'saída de dinheiro' a débito por analogia com o extrato bancário.","comoBancaPensa":"Oferece uma descrição factual correta que empurra o candidato para o lançamento invertido."}},"CT-046":{"cognitivo":{"motivo":"Fixar que pagamento antecipado gera ativo, não despesa imediata.","palavraCritica":"no ativo"},"comentario":{"resolucao":"CERTO. No momento do pagamento não há despesa, e sim um DIREITO: a entidade pagou e passará a receber o benefício ao longo do tempo. Por isso o registro inicial é no ativo, e a apropriação ao resultado acompanha a fluência do prazo — é aplicação direta do regime de competência. A contrapartida existe do outro lado: valor recebido antecipadamente por serviço ainda não prestado é PASSIVO (receita antecipada), porque gera obrigação de entregar. Pagou adiantado, ativo; recebeu adiantado, passivo.","fundamento":"Doutrina contábil — regime de competência; Lei 6.404/1976, art. 179, I.","macete":"Pagou antes: ativo. Recebeu antes: passivo.","erroComum":"Reconhecer despesa integral no desembolso, seguindo o regime de caixa.","comoBancaPensa":"Testa a aplicação do regime de competência num caso concreto de fluxo antecipado."}},"CT-047":{"cognitivo":{"motivo":"Cobrar a natureza de passivo do adiantamento recebido.","palavraCritica":"por já estar disponível em caixa"},"comentario":{"resolucao":"ERRADO. Receber dinheiro não é ganhar receita. Enquanto o serviço não é prestado, a entidade tem OBRIGAÇÃO de entregá-lo — o registro é no passivo, como receita antecipada ou adiantamento de clientes, e só migra para o resultado quando a prestação ocorrer. A justificativa do item, de que o valor já está em caixa, é exatamente o raciocínio do regime de caixa, que não é o adotado pela contabilidade societária. Note a simetria com as despesas antecipadas, que são ativo pela razão inversa.","fundamento":"Doutrina contábil — regime de competência; CPC 47 (reconhecimento de receita).","macete":"Recebeu sem entregar: passivo, não receita.","erroComum":"Reconhecer receita pela disponibilidade financeira.","comoBancaPensa":"Usa a existência do dinheiro em caixa como justificativa aparentemente irrefutável."}},"CT-048":{"cognitivo":{"motivo":"Separar a igualdade de valores da quantidade de contas envolvidas.","palavraCritica":"uma única"},"comentario":{"resolucao":"ERRADO. O método exige igualdade entre a soma dos débitos e a soma dos créditos, não que haja uma conta de cada lado. Lançamentos de segunda, terceira e quarta fórmulas envolvem várias contas: uma compra parte à vista e parte a prazo debita Mercadorias e credita Caixa E Fornecedores, e continua obedecendo às partidas dobradas. O item confunde a regra de equivalência de VALORES com uma inexistente regra de QUANTIDADE de contas.","fundamento":"Doutrina contábil — método das partidas dobradas; fórmulas de lançamento.","macete":"O que tem de bater é o valor, não o número de contas.","erroComum":"Generalizar a primeira fórmula de lançamento como se fosse a única.","comoBancaPensa":"Converte o caso mais simples em regra geral obrigatória."}},"CT-049":{"cognitivo":{"motivo":"Cobrar a inversão entre as definições dos dois regimes.","palavraCritica":"regime de caixa"},"comentario":{"resolucao":"ERRADO. A definição apresentada é a do regime de COMPETÊNCIA, e o item a rotula como regime de caixa. O de caixa faz o oposto: reconhece receitas e despesas apenas quando há efetivo recebimento ou pagamento, ignorando o momento do fato gerador. A pista está na própria frase — 'independentemente da movimentação financeira' é incompatível com um regime que se chama, justamente, de caixa. Contradição interna é o sinal a procurar.","fundamento":"Doutrina contábil — regimes de escrituração; CPC 00 (Estrutura Conceitual).","macete":"Caixa olha o dinheiro. Competência olha o fato gerador.","erroComum":"Validar a definição por ela ser correta — só que do outro regime.","comoBancaPensa":"Troca o rótulo mantendo o conteúdo íntegro: troca-conceito na forma mais pura."}},"CT-050":{"cognitivo":{"motivo":"Cobrar a inversão do critério de reconhecimento da receita.","palavraCritica":"somente no momento do recebimento"},"comentario":{"resolucao":"ERRADO — o item inverte os dois lados. Pelo regime de competência a receita é reconhecida quando a entidade cumpre sua obrigação de desempenho, tipicamente na entrega do produto ou na prestação do serviço, e não quando recebe. Uma venda a prazo em dezembro é receita de dezembro, ainda que o dinheiro entre em março. O critério condicionado ao recebimento é o do regime de caixa, e a menção à irrelevância da entrega é o oposto exato do que a norma exige.","fundamento":"Doutrina contábil — regime de competência; CPC 47, obrigação de desempenho.","macete":"Competência: entregou, é receita. Recebeu ou não, é outra conversa.","erroComum":"Ler 'competência' e associar ao momento em que o dinheiro se torna disponível.","comoBancaPensa":"Aplica ao regime nomeado o critério do regime oposto."}},"CT-051":{"cognitivo":{"motivo":"Fixar o critério de reconhecimento da despesa, simétrico ao da receita.","palavraCritica":"independentemente do respectivo fluxo de caixa"},"comentario":{"resolucao":"CERTO. A despesa pertence ao período em que é incorrida, isto é, em que o bem foi consumido ou o serviço utilizado, e não ao período do pagamento. A energia elétrica consumida em dezembro e paga em janeiro é despesa de dezembro. É a mesma lógica aplicada à receita, e é ela que dá sentido às contas de provisão e de valores a pagar: elas existem justamente para acomodar a distância entre o fato e o desembolso.","fundamento":"Doutrina contábil — regime de competência; CPC 00 (Estrutura Conceitual).","macete":"Incorreu, é despesa. Pagar é evento financeiro, não contábil.","erroComum":"Condicionar o reconhecimento da despesa ao desembolso.","comoBancaPensa":"Item literal correto, âncora para as inversões cobradas nos itens vizinhos."}},"CT-052":{"cognitivo":{"motivo":"Exigir a aplicação numérica do regime, distinguindo dos valores de caixa.","palavraCritica":"pelo regime de competência"},"comentario":{"resolucao":"CERTO. Pelo regime de competência interessam a receita ganha e a despesa incorrida, não o que transitou pelo caixa: 240.000 − 186.000 = 54.000 de lucro. Os valores recebidos e pagos são distratores — pelo regime de CAIXA o resultado seria 205.000 − 178.000 = 27.000, e é esse número que a banca costuma oferecer como se fosse o da competência. Repare que a diferença entre os dois resultados (27.000) corresponde exatamente ao que ficou a receber menos o que ficou a pagar: 35.000 − 8.000.","fundamento":"Doutrina contábil — regime de competência x regime de caixa na apuração do resultado.","macete":"Competência usa vendeu e incorreu. Caixa usa recebeu e pagou.","erroComum":"Calcular com os valores efetivamente movimentados no caixa.","comoBancaPensa":"Fornece os quatro números para que o candidato escolha o par errado."}},"CT-053":{"cognitivo":{"motivo":"Exigir o cálculo pelo regime de caixa, invertendo o par de valores relevantes.","palavraCritica":"regime de caixa"},"comentario":{"resolucao":"CERTO. Pelo regime de caixa contam apenas os valores efetivamente movimentados: 62.000 recebidos − 65.000 pagos = −3.000, ou seja, prejuízo de 3.000. Pelo regime de competência o quadro se inverte: 90.000 − 71.000 = 19.000 de lucro. O caso mostra por que o regime importa — a mesma entidade, no mesmo período, apresenta prejuízo por um critério e lucro pelo outro, e é essa divergência que justifica a competência ser a regra societária.","fundamento":"Doutrina contábil — regime de caixa x regime de competência.","macete":"Caixa é só o que entrou menos o que saiu.","erroComum":"Aplicar os valores de competência ao regime de caixa.","comoBancaPensa":"Inverte o comando em relação ao item anterior, cobrando atenção ao regime pedido."}},"CT-054":{"cognitivo":{"motivo":"Cobrar a universalidade do regime de competência na escrituração contábil.","palavraCritica":"somente"},"comentario":{"resolucao":"ERRADO. A competência é o regime da escrituração contábil de todas as entidades, independentemente do porte — inclusive as pequenas e médias, cuja norma específica é construída sobre ele. O que varia com o porte é o conjunto de demonstrações exigidas e o nível de divulgação, não o regime de reconhecimento. Não confundir com regimes de apuração TRIBUTÁRIA: ali existem opções, como o lucro presumido, mas isso é matéria fiscal, distinta da escrituração contábil.","fundamento":"Lei 6.404/1976, art. 177; CPC PME; doutrina contábil — regime de competência.","macete":"Competência vale para todas. Porte muda divulgação, não regime.","erroComum":"Transportar para a contabilidade as opções existentes na apuração tributária.","comoBancaPensa":"Cria uma faculdade por porte, apoiada na existência real de regimes fiscais opcionais."}},"CT-055":{"cognitivo":{"motivo":"Fixar a razão de ser da competência como regime da contabilidade societária.","palavraCritica":"desempenho econômico"},"comentario":{"resolucao":"CERTO. É a justificativa da Estrutura Conceitual para a competência ser a regra: ao reconhecer os efeitos das transações quando ocorrem, e não quando o dinheiro se movimenta, ela informa melhor sobre o desempenho ECONÔMICO da entidade. O regime de caixa informa sobre o desempenho FINANCEIRO — igualmente relevante, e por isso a Demonstração dos Fluxos de Caixa existe e é obrigatória. Não são regimes concorrentes: um mede geração de riqueza, o outro, geração de liquidez.","fundamento":"CPC 00 (Estrutura Conceitual); Lei 6.404/1976, art. 176.","macete":"Competência mede riqueza. Caixa mede liquidez. A DFC existe para o segundo.","erroComum":"Tratar o regime de caixa como irrelevante para a contabilidade.","comoBancaPensa":"Cobra a fundamentação conceitual, e não apenas a definição operacional."}},"CT-056":{"cognitivo":{"motivo":"Fixar o art. 35 da Lei 4.320, que combina os dois regimes em um único dispositivo.","palavraCritica":"regime misto"},"comentario":{"resolucao":"CERTO. É o art. 35 da Lei 4.320/1964: receita pelo regime de CAIXA (arrecadação) e despesa pelo regime de COMPETÊNCIA (empenho). A combinação é o que a doutrina chama de regime misto, e vale para a execução ORÇAMENTÁRIA. Atenção ao recorte, porque é onde a banca ataca: a contabilidade PATRIMONIAL do setor público segue a competência integral, conforme as normas aplicadas ao setor público. Item que estenda o regime misto à contabilidade patrimonial estaria errado.","fundamento":"Lei 4.320/1964, art. 35; NBC TSP — Estrutura Conceitual.","macete":"Receita arrecadada, despesa empenhada. Misto, e só na execução orçamentária.","erroComum":"Inverter os regimes ou estender o misto à contabilidade patrimonial pública.","comoBancaPensa":"Cobra o único dispositivo brasileiro que combina os dois regimes por lei."}},"CT-057":{"cognitivo":{"motivo":"Cobrar a inversão dos critérios do art. 35, com uso de termo tecnicamente impossível.","palavraCritica":"receitas ... empenhadas"},"comentario":{"resolucao":"ERRADO, e o erro é duplo. Primeiro, os critérios estão trocados: a lei vincula a receita à ARRECADAÇÃO e a despesa ao EMPENHO, não o contrário. Segundo, 'receita empenhada' é impossibilidade técnica — empenho é estágio da DESPESA, jamais da receita. Reconhecer essa incompatibilidade de vocabulário permite eliminar o item sem sequer lembrar do art. 35: nenhum dispositivo poderia falar em empenhar receita.","fundamento":"Lei 4.320/1964, arts. 35, 58 e 60.","macete":"Empenho é estágio de despesa. Receita não se empenha.","erroComum":"Aceitar a inversão por reconhecer os dois termos como do vocabulário da lei.","comoBancaPensa":"Embaralha termos verdadeiros do mesmo diploma, criando combinação impossível."}},"CT-058":{"cognitivo":{"motivo":"Cobrar que a forma do recebimento é irrelevante para o reconhecimento por competência.","palavraCritica":"depende"},"comentario":{"resolucao":"ERRADO. No regime de competência o recebimento é irrelevante para o reconhecimento — tanto a existência quanto a forma. Reconhece-se a receita quando a entidade cumpre a obrigação de desempenho, ainda que nada tenha entrado e ainda que a contraprestação venha a ser recebida em bens, títulos ou serviços. O item cria uma condição de forma que nem o regime de caixa impõe, já que este se satisfaz com qualquer ingresso.","fundamento":"Doutrina contábil — regime de competência; CPC 47.","macete":"Competência não pergunta se recebeu, muito menos como.","erroComum":"Confundir reconhecimento contábil com liquidação financeira.","comoBancaPensa":"Adiciona um requisito de forma sobre um critério que já dispensa o próprio recebimento."}},"CT-059":{"cognitivo":{"motivo":"Fixar a base legal da escrituração e o princípio da uniformidade.","palavraCritica":"uniformes no tempo"},"comentario":{"resolucao":"CERTO. É o art. 177 da Lei 6.404/1976. A uniformidade no tempo é o que torna as demonstrações comparáveis entre exercícios — mudar de critério a cada ano permitiria maquiar tendências. Isso não significa imutabilidade: a alteração é possível, mas exige divulgação em nota explicativa dos efeitos sobre o resultado. O mesmo artigo é a âncora legal da competência na escrituração societária.","fundamento":"Lei 6.404/1976, art. 177, caput.","macete":"Uniformidade permite comparar exercícios. Mudou, tem de explicar em nota.","erroComum":"Ler uniformidade como proibição absoluta de mudar de critério.","comoBancaPensa":"Transcreve dispositivo longo, apostando que a extensão iniba a conferência."}},"CT-060":{"cognitivo":{"motivo":"Cobrar a distinção entre pagamento do principal e pagamento de juros.","palavraCritica":"juros"},"comentario":{"resolucao":"ERRADO. Pagar JUROS é despesa: reduz o ativo sem reduzir obrigação equivalente, e portanto diminui o patrimônio líquido — fato modificativo diminutivo. O raciocínio do item vale para o pagamento do PRINCIPAL, esse sim permutativo, porque a saída de caixa é compensada pela baixa da dívida. A mesma operação bancária comporta os dois fatos, e a banca aproveita a proximidade para trocar um pelo outro.","fundamento":"Doutrina contábil — classificação dos fatos administrativos.","macete":"Principal: permutativo. Juros: modificativo diminutivo.","erroComum":"Tratar toda saída de caixa vinculada a empréstimo como permutativa.","comoBancaPensa":"Aplica a um componente da operação a classificação que só vale para o outro."}},"CT-061":{"cognitivo":{"motivo":"Fixar o conceito de fato misto a partir de operação corriqueira.","palavraCritica":"fato misto"},"comentario":{"resolucao":"CERTO. A operação tem duas naturezas simultâneas: a baixa da duplicata contra a entrada em caixa é permuta dentro do ativo; o desconto concedido é despesa, que reduz o patrimônio líquido. Reunidas no mesmo fato, caracterizam o fato misto — também chamado composto. Ele é diminutivo quando envolve despesa, como aqui, e aumentativo quando envolve receita, caso do recebimento com juros por atraso.","fundamento":"Doutrina contábil — fatos mistos ou compostos.","macete":"Misto = permuta + variação de PL na mesma operação.","erroComum":"Classificar só pela parte mais visível da operação.","comoBancaPensa":"Usa operação rotineira que a maioria classifica pela metade."}},"CT-062":{"cognitivo":{"motivo":"Separar ato de fato administrativo e localizar o registro correto.","palavraCritica":"fato administrativo modificativo"},"comentario":{"resolucao":"ERRADO. Trata-se de ATO administrativo relevante, não de fato: nada no patrimônio se altera no momento da assinatura da fiança, embora exista risco de vir a alterar. Por isso o registro se dá em contas de COMPENSAÇÃO, e não em conta de resultado — não há despesa a reconhecer enquanto a garantia não for executada. Se e quando for, aí sim nasce o fato administrativo, com efeito real sobre o patrimônio.","fundamento":"Doutrina contábil — atos e fatos administrativos; contas de compensação.","macete":"Ato: nada mudou ainda, vai para compensação. Fato: mudou, vai para o balanço.","erroComum":"Reconhecer despesa no momento em que a garantia é prestada.","comoBancaPensa":"Trata como fato aquilo que a doutrina classifica como ato, e desloca o registro."}},"CT-063":{"cognitivo":{"motivo":"Cobrar quais erros o balancete NÃO detecta, ponto central da sua utilidade real.","palavraCritica":"assegura"},"comentario":{"resolucao":"ERRADO. O balancete comprova apenas a igualdade aritmética entre débitos e créditos. Passam por ele intactos: o lançamento feito em conta errada mas de mesma natureza, o fato inteiramente omitido, o lançamento duplicado e a inversão entre a conta debitada e a creditada quando os valores coincidem. Em todos esses casos os totais batem e a escrituração está errada. Por isso o balancete é instrumento de VERIFICAÇÃO, não de validação.","fundamento":"Doutrina contábil — balancete de verificação e limites de detecção de erros.","macete":"Bater não é estar certo. Conta trocada e fato omitido não desequilibram nada.","erroComum":"Tratar o equilíbrio aritmético como atestado de correção da escrituração.","comoBancaPensa":"Eleva um instrumento de conferência parcial à condição de garantia integral."}},"CT-064":{"cognitivo":{"motivo":"Cobrar que o balancete abrange todas as contas com saldo, inclusive as de resultado.","palavraCritica":"exclusivamente"},"comentario":{"resolucao":"ERRADO. O balancete relaciona TODAS as contas com saldo na data, patrimoniais e de resultado. As contas de resultado acumulam movimento ao longo do exercício e por isso aparecem — o que ocorre ao final não é a apuração de seus saldos, e sim o ENCERRAMENTO, quando são zeradas contra a conta de apuração do resultado. Confundir acumular saldo com apurar resultado é a raiz do erro.","fundamento":"Doutrina contábil — balancete de verificação; encerramento das contas de resultado.","macete":"Balancete mostra tudo que tem saldo. Encerramento é que zera o resultado.","erroComum":"Supor que contas de resultado só existem no encerramento.","comoBancaPensa":"Usa uma verdade sobre o encerramento para restringir indevidamente o balancete."}},"CT-065":{"cognitivo":{"motivo":"Fixar que permutativo se define pela ausência de efeito no PL, não pela ausência de variação nos grupos.","palavraCritica":"ainda que aumente"},"comentario":{"resolucao":"CERTO. Permutativo não significa que nada muda de tamanho — significa que o PATRIMÔNIO LÍQUIDO não se altera. Aqui o ativo cresce pelo veículo e o passivo cresce pela obrigação, na mesma medida, e o PL permanece intacto. Esse tipo é chamado de permutativo aumentativo, ou quantitativo-qualitativo. Item que exija que o total do ativo permaneça inalterado para haver permuta estaria errado.","fundamento":"Doutrina contábil — classificação dos fatos administrativos.","macete":"Permutativo é o que não mexe no PL, mesmo aumentando ativo e passivo.","erroComum":"Exigir que o total do balanço permaneça constante.","comoBancaPensa":"Contraexemplo: o item afirma o que o candidato tenderia a negar por reflexo."}},"CT-066":{"cognitivo":{"motivo":"Contraexemplo: aqui a afirmação categórica é verdadeira e deve ser marcada CERTO.","palavraCritica":"necessariamente"},"comentario":{"resolucao":"CERTO — e o termo categórico procede. Caixa registra dinheiro em espécie sob guarda da entidade, e não há como entregar numerário que não se tem; saldo credor em caixa é impossibilidade material, sinalizando lançamento omitido, invertido ou registrado em conta errada. Não confundir com BANCOS, onde o saldo credor é perfeitamente possível e significa conta garantida ou cheque especial utilizado — ali a instituição adiantou recursos, e o saldo credor representa dívida real.","fundamento":"Doutrina contábil — natureza das contas do disponível.","macete":"Caixa credor: erro. Bancos credor: cheque especial, e é dívida.","erroComum":"Marcar ERRADO por reflexo diante de 'necessariamente'.","comoBancaPensa":"Usa termo absoluto verdadeiro para punir quem eliminou o item sem pensar."}},"CT-067":{"cognitivo":{"motivo":"Cobrar a diferença entre disponibilidade em espécie e conta bancária com limite.","palavraCritica":"necessariamente"},"comentario":{"resolucao":"ERRADO. Bancos admite saldo credor sem erro algum: significa que a entidade utilizou limite de conta garantida ou cheque especial, e o saldo credor expressa uma obrigação real perante a instituição financeira, devendo ser reclassificado para o passivo circulante na apresentação do balanço. A analogia com caixa não se sustenta, porque ali o saldo credor é materialmente impossível. Mesmo grupo, comportamentos diferentes.","fundamento":"Doutrina contábil — disponibilidades; Lei 6.404/1976, art. 178, § 1º.","macete":"Bancos pode ficar credor — vira passivo, não erro.","erroComum":"Estender a impossibilidade do caixa a todas as disponibilidades.","comoBancaPensa":"Constrói a generalização a partir de um item anterior verdadeiro, criando armadilha em par."}},"CT-068":{"cognitivo":{"motivo":"Ligar um instituto patrimonial ao regime que o justifica.","palavraCritica":"desembolso ocorreu integralmente em um único momento"},"comentario":{"resolucao":"CERTO. A depreciação é a expressão mais visível da competência: a entidade paga o bem de uma vez, mas o consome ao longo de anos, e a despesa deve aparecer nos exercícios em que o benefício é fruído — não naquele em que o dinheiro saiu. Sob regime de caixa a máquina inteira viraria despesa no ano da compra, distorcendo o resultado daquele exercício e dos seguintes. Vale notar que a depreciação não gera saída de caixa; é despesa sem desembolso, e por isso é somada de volta na Demonstração dos Fluxos de Caixa pelo método indireto.","fundamento":"Lei 6.404/1976, art. 183, § 2º; CPC 27; doutrina contábil — regime de competência.","macete":"Pagou uma vez, consome por anos — a competência distribui.","erroComum":"Ver a depreciação como ajuste fiscal em vez de aplicação do regime.","comoBancaPensa":"Cobra a conexão entre um instituto concreto e o princípio que o fundamenta."}},"CT-069":{"cognitivo":{"motivo":"Cobrar a localização da provisão retificadora, que o nome sugere ser passivo.","palavraCritica":"passivo circulante"},"comentario":{"resolucao":"ERRADO. É conta RETIFICADORA DO ATIVO, credora, apresentada como redução das Contas a Receber — ajusta o valor do direito ao montante que se espera efetivamente realizar. Não há obrigação da entidade perante ninguém: quem deve é o cliente, e o risco é de não receber, não de ter de pagar. A palavra 'provisão' induz ao erro por lembrar as provisões do passivo, como a de férias e a para contingências, essas sim obrigações.","fundamento":"Lei 6.404/1976, art. 183, I; CPC 48; doutrina contábil — contas retificadoras.","macete":"Provisão para perdas com recebíveis retifica ATIVO. Provisão de férias é passivo.","erroComum":"Classificar pela palavra 'provisão', sem perguntar quem deve a quem.","comoBancaPensa":"Explora um termo que aparece nos dois lados do balanço com naturezas opostas."}},"CT-070":{"cognitivo":{"motivo":"Aplicar concretamente os limites de detecção do balancete.","palavraCritica":"desequilíbrio"},"comentario":{"resolucao":"ERRADO. O valor foi debitado e creditado corretamente, apenas na conta errada — e como ambas são despesas, de mesma natureza devedora, as somas continuam iguais. O balancete fecha e o erro permanece invisível ali. A distorção existe e é real: o resultado total está certo, mas a composição das despesas está errada, o que compromete a análise por natureza de gasto. Erros dessa espécie só aparecem na conciliação de cada conta com seus documentos de suporte.","fundamento":"Doutrina contábil — balancete de verificação; erros não detectáveis pela igualdade aritmética.","macete":"Conta errada de mesma natureza: balancete fecha e o erro passa.","erroComum":"Supor que todo erro de escrituração desequilibra o balancete.","comoBancaPensa":"Cobra em caso concreto o limite teórico que o item anterior enuncia em abstrato."}},"CT-071":{"cognitivo":{"motivo":"Cobrar que a lei fixa a duração do exercício, não sua data de encerramento.","palavraCritica":"obrigatoriamente"},"comentario":{"resolucao":"ERRADO. A Lei 6.404/1976 fixa que o exercício social tem DURAÇÃO de um ano e que a data do término será estabelecida no estatuto — não impõe coincidência com o ano civil. Muitas companhias encerram em 30 de junho ou em 31 de março, e nada disso afeta a aplicação do regime de competência, que independe do calendário adotado. A exceção legal é a constituição da companhia ou a alteração estatutária, quando o exercício pode ter duração diversa.","fundamento":"Lei 6.404/1976, art. 175, caput e parágrafo único.","macete":"A lei fixa a duração (um ano), não a data de encerramento.","erroComum":"Confundir exercício social com ano-calendário fiscal.","comoBancaPensa":"Cria obrigatoriedade de data onde a lei delega ao estatuto."}},"CT-072":{"cognitivo":{"motivo":"Fixar o ciclo de vida das contas de resultado, que distingue transitórias de permanentes.","palavraCritica":"saldo zero"},"comentario":{"resolucao":"CERTO. Contas de resultado são TRANSITÓRIAS: medem desempenho de um período determinado e, cumprida essa função, são zeradas contra a apuração do resultado do exercício. O saldo apurado migra então para o Patrimônio Líquido. As patrimoniais, ao contrário, são PERMANENTES — o saldo de Caixa em 31 de dezembro é exatamente o saldo inicial de 1º de janeiro. É essa diferença que explica por que Lucros Acumulados não é conta de resultado, embora receba o resultado.","fundamento":"Doutrina contábil — encerramento do exercício; Lei 6.404/1976, art. 187.","macete":"Resultado é transitória e zera. Patrimonial é permanente e continua.","erroComum":"Supor que o saldo das contas de resultado é transportado para o exercício seguinte.","comoBancaPensa":"Cobra o mecanismo que fundamenta a classificação cobrada em outros itens."}},"CT-073":{"cognitivo":{"motivo":"Cobrar a vedação de rasura e o procedimento correto de retificação.","palavraCritica":"rasura"},"comentario":{"resolucao":"ERRADO. A escrituração não admite rasura, emenda ou entrelinha — o registro é feito em ordem cronológica e não pode ser apagado. A correção se faz por ESTORNO, com lançamento de igual valor e sentido inverso ao equivocado, seguido do lançamento correto; alternativamente, por transferência ou complementação, conforme o caso. O rastro do erro e da correção permanece visível, e é justamente isso que dá confiabilidade à escrituração.","fundamento":"Lei 6.404/1976, art. 177; NBC ITG 2000 — escrituração contábil.","macete":"Não se rasura escrituração: estorna-se.","erroComum":"Admitir correção por rasura visada, como em documentos administrativos comuns.","comoBancaPensa":"Importa da praxe administrativa um procedimento que a norma contábil veda."}},"CT-074":{"cognitivo":{"motivo":"Separar o regime da execução orçamentária do da contabilidade patrimonial pública.","palavraCritica":"contabilidade patrimonial"},"comentario":{"resolucao":"ERRADO. O regime misto do art. 35 da Lei 4.320/1964 rege a EXECUÇÃO ORÇAMENTÁRIA. A contabilidade PATRIMONIAL do setor público segue o regime de competência integral, reconhecendo as variações patrimoniais quando ocorrem os fatos geradores, independentemente da arrecadação ou do pagamento. As duas dimensões convivem no mesmo ente e por isso a informação contábil pública é apresentada em subsistemas distintos — orçamentário e patrimonial —, cada um com seu critério.","fundamento":"Lei 4.320/1964, art. 35; NBC TSP — Estrutura Conceitual; MCASP.","macete":"Orçamentário: misto. Patrimonial: competência integral.","erroComum":"Estender o art. 35 a toda a contabilidade do setor público.","comoBancaPensa":"Generaliza para o sistema inteiro uma regra que vale para um de seus subsistemas."}},"CT-075":{"cognitivo":{"motivo":"Testar se o candidato marca ERRADO só por ver 'único', mesmo quando a restrição é a da própria lei.","palavraCritica":"único"},"comentario":{"resolucao":"CERTO. O art. 1.180 do Código Civil é expresso: além dos demais livros exigidos por lei, é indispensável o Diário, que pode ser substituído por fichas no caso de escrituração mecanizada ou eletrônica. A palavra 'indispensável' aparece no texto legal referida a um único livro. O Razão é auxiliar e o Caixa deixa de ser exigido quando a entidade escritura o Diário com individuação. Note que a ressalva do enunciado — 'ressalvadas as exigências específicas previstas em leis especiais' — reproduz exatamente o 'além dos demais livros exigidos por lei' do dispositivo, e é ela que torna a restrição legítima.","fundamento":"Código Civil, arts. 1.180 e 1.181; Lei 6.404/1976, art. 177.","macete":"Diário: indispensável por lei. Razão: auxiliar. Plano de contas: nem livro é.","erroComum":"Marcar ERRADO por reflexo diante de 'único', sem checar se a exclusividade é a da lei.","comoBancaPensa":"Usa o formato restritivo que costuma sinalizar erro para punir quem responde sem ler o conteúdo."}},"CT-076":{"cognitivo":{"motivo":"Fixar o alcance da depreciação e separá-la de amortização e exaustão.","palavraCritica":"somente"},"comentario":{"resolucao":"CERTO. Depreciação é a alocação sistemática do valor depreciável de um bem tangível do imobilizado ao longo de sua vida útil. Terreno tem vida útil indefinida e por isso não se deprecia — ainda que a edificação construída sobre ele se deprecie normalmente. Bens intangíveis com vida útil definida sofrem AMORTIZAÇÃO, não depreciação; recursos naturais esgotáveis sofrem EXAUSTÃO. As três figuras são espécies do mesmo gênero, e a banca troca uma pela outra com frequência.","fundamento":"CPC 27 (Ativo Imobilizado); Lei 6.404/1976, art. 183, § 2º.","macete":"Tangível deprecia, intangível amortiza, recurso natural exaure. Terreno, nada.","erroComum":"Rejeitar o 'somente' sem perceber que o recorte descrito é exatamente o da norma.","comoBancaPensa":"Enuncia corretamente um limite técnico com a palavra que o candidato associa a erro."}},"CT-077":{"cognitivo":{"motivo":"Cobrar as formalidades intrínsecas literalmente exigidas pelo Código Civil.","palavraCritica":"vedados"},"comentario":{"resolucao":"CERTO. O enunciado reproduz o art. 1.183 do Código Civil quase palavra por palavra. Todas as exigências listadas — idioma e moeda nacionais, forma contábil, ordem cronológica de dia, mês e ano, e a vedação a espaços em branco, entrelinhas, borrões, rasuras, emendas e transportes para as margens — são as chamadas formalidades INTRÍNSECAS da escrituração. É por causa dessa vedação que a correção de erro se faz por estorno, transferência ou complementação, e nunca por rasura.","fundamento":"Código Civil, art. 1.183; ITG 2000 (R1).","macete":"Formalidade extrínseca é o livro por fora (termos, autenticação); intrínseca é o registro por dentro.","erroComum":"Supor que a lista é longa demais para ser toda legal e marcar ERRADO por excesso.","comoBancaPensa":"Acumula exigências verdadeiras até o enunciado 'parecer' inventado."}},"CT-078":{"cognitivo":{"motivo":"Cobrar a exigência de dupla assinatura e de transcrição das demonstrações no Diário.","palavraCritica":"devem ser lançados no livro Diário"},"comentario":{"resolucao":"CERTO. É o § 2º do art. 1.184 do Código Civil. O Diário não recebe apenas os lançamentos diários com individuação e clareza: ao fim do exercício, o balanço patrimonial e o balanço de resultado econômico são nele transcritos, com dupla assinatura — do contabilista habilitado e do empresário ou da sociedade. A dupla assinatura reparte a responsabilidade: técnica de um lado, de gestão do outro. Quem estuda apenas o conteúdo das demonstrações e ignora sua formalização de registro erra este item.","fundamento":"Código Civil, art. 1.184, §§ 1º e 2º.","macete":"Diário fecha o exercício: recebe o balanço e exige duas assinaturas.","erroComum":"Tratar a transcrição no Diário como praxe facultativa e não como exigência legal.","comoBancaPensa":"Explora a lacuna entre saber montar a demonstração e saber onde ela é formalizada."}},"CT-079":{"cognitivo":{"motivo":"Confunde o OBJETO da ciência com o INSTRUMENTO de registro.","palavraCritica":"grupos de contas"},"comentario":{"resolucao":"ERRADO. O OBJETO da contabilidade é o PATRIMÔNIO da entidade — o conjunto de bens, direitos e obrigações — e suas variações. As contas são apenas o INSTRUMENTO pelo qual esse objeto é registrado e classificado; confundir os dois é como dizer que o objeto da medicina é o prontuário. A distinção não é acadêmica: é dela que decorre o campo de aplicação (as entidades com patrimônio) e a finalidade (fornecer informação útil sobre esse patrimônio para a tomada de decisão). Um segundo detalhe do enunciado também merece atenção: nem todo evento que a contabilidade registra afeta o patrimônio em valor — os fatos permutativos apenas o recompõem, como em CT-084.","fundamento":"Teoria da contabilidade — objeto, campo de aplicação e finalidade.","macete":"Objeto é o patrimônio. Conta é ferramenta.","erroComum":"Definir a contabilidade pela técnica de escrituração.","comoBancaPensa":"Troca objeto por instrumento, numa frase que soa correta a quem só conhece a rotina de lançamentos."}},"CT-080":{"cognitivo":{"motivo":"Aplicação numérica direta da equação patrimonial, com o resultado como incógnita.","palavraCritica":"antes da apuração do resultado"},"comentario":{"resolucao":"CERTO. Pela equação fundamental, Ativo = Passivo + Patrimônio Líquido. Como o resultado ainda não foi incorporado ao PL, ele entra como parcela a apurar: 150 = 125 + 30 + R, o que dá R = 150 - 155 = -5 mil. Valor negativo significa PREJUÍZO de R$ 5 mil. Confira pela lógica, sem a conta: o passivo somado ao PL informado (155) supera o ativo (150), e essa diferença de 5 só se fecha com um resultado negativo. Note que aqui o PL de 30 mil ainda é positivo — a entidade tem prejuízo no exercício sem estar em passivo a descoberto, situação que só ocorreria se o PL final ficasse negativo.","fundamento":"Equação fundamental do patrimônio: A = P + PL.","macete":"Passivo + PL maior que o Ativo? Falta resultado negativo para fechar.","erroComum":"Somar o resultado no lugar de subtrair, invertendo o sinal.","comoBancaPensa":"Dá três valores e pede o sinal do quarto; o cálculo é trivial, o erro está no arranjo."}},"CT-081":{"cognitivo":{"motivo":"Exige classificar doze contas, incluindo quatro retificadoras — que são a armadilha inteira.","palavraCritica":"juros passivos a transcorrer ... ações em tesouraria"},"comentario":{"resolucao":"CERTO — são 6 de cada. DEVEDORAS: caixa, bancos, instalações e veículos (contas do ativo), mais juros passivos a transcorrer e ações em tesouraria. CREDORAS: impostos a recolher, empréstimos a pagar, capital social e reserva para contingências, mais depreciação acumulada e duplicatas descontadas. O item vive das RETIFICADORAS, que têm natureza invertida em relação ao grupo em que aparecem: depreciação acumulada retifica o ativo imobilizado e por isso é credora; ações em tesouraria retificam o patrimônio líquido e por isso são devedoras; juros passivos a transcorrer retificam o passivo e são devedores; duplicatas descontadas retificam o ativo (ou figuram no passivo) e são credoras. Quem classifica só por grupo erra as quatro.","fundamento":"Mecanismo de débito e crédito; contas retificadoras.","macete":"Retificadora tem sempre o sinal contrário ao do grupo que ela corrige.","erroComum":"Classificar tudo pelo grupo (ativo devedor, passivo credor) e ignorar as retificadoras.","comoBancaPensa":"Monta a lista para que o resultado só empate se todas as retificadoras forem classificadas certo."}},"CT-082":{"cognitivo":{"motivo":"A empresa é apenas responsável tributária: retém valor de terceiro e assume obrigação de repassar.","palavraCritica":"retido na fonte"},"comentario":{"resolucao":"CERTO. No reconhecimento da folha pelo regime de competência, a empresa debita a despesa com salários pelo valor BRUTO e credita duas obrigações: salários a pagar (o líquido devido ao empregado) e IRRF a recolher (o valor retido, devido ao Fisco). Ambas são passivo circulante, e por isso o registro aumenta esse grupo. O ponto conceitual é que a empresa não é contribuinte desse imposto — é RESPONSÁVEL TRIBUTÁRIA: retém dinheiro do empregado e o repassa ao Fisco no prazo legal, funcionando como intermediária. Daí o IRRF não ser despesa da empresa, e sim redutor do que ela paga ao empregado.","fundamento":"Regime de competência; contabilização de folha de pagamento e retenções.","macete":"O que a empresa retém de terceiro vira obrigação dela até repassar.","erroComum":"Tratar o IRRF sobre a folha como despesa tributária da empresa.","comoBancaPensa":"Cobra o efeito patrimonial de um lançamento de rotina, e não o lançamento em si."}},"CT-083":{"cognitivo":{"motivo":"Confunde o momento do DESEMBOLSO com o da APROPRIAÇÃO — o núcleo do regime de competência.","palavraCritica":"pagamento antecipado"},"comentario":{"resolucao":"ERRADO. Pelo regime de COMPETÊNCIA, a despesa é reconhecida no período em que é INCORRIDA, não naquele em que é paga. Encargos financeiros pagos antecipadamente sobre empréstimo plurianual são registrados em conta retificadora do passivo — 'encargos financeiros a transcorrer' — e apropriados ao resultado PRO RATA TEMPORIS, ao longo de todos os exercícios de vigência do contrato. Portanto o lucro do ano anterior é reduzido apenas pela parcela daquele período, e os exercícios seguintes sofrem impacto sim, cada um pela sua fração. É o mesmo mecanismo, do lado do ativo, das despesas antecipadas como aluguel e seguro pagos adiantados.","fundamento":"Regime de competência; encargos financeiros a transcorrer como conta retificadora do passivo.","macete":"Pagou tudo de uma vez, apropria aos poucos. Caixa e competência não se confundem.","erroComum":"Reconhecer a despesa inteira no exercício do desembolso.","comoBancaPensa":"Aproveita a intuição de caixa, que é a forma natural de pensar de quem não domina competência."}},"CT-084":{"cognitivo":{"motivo":"Critério único: o fato altera ou não o valor do patrimônio líquido.","palavraCritica":"à vista"},"comentario":{"resolucao":"CERTO. Fato PERMUTATIVO é o que apenas troca elementos patrimoniais entre si, sem alterar o valor do patrimônio líquido. A compra à vista faz exatamente isso: o estoque aumenta e o caixa diminui, na mesma importância, dentro do ativo. Compare com as outras espécies: MODIFICATIVO altera o PL (pagamento de uma despesa, recebimento de uma receita) e MISTO combina os dois efeitos (pagar uma duplicata com desconto obtido — permuta caixa por dívida e ainda gera receita). A palavra 'à vista' é decisiva: a prazo, o fato continua permutativo (estoque aumenta, fornecedores aumentam), mas por outro arranjo.","fundamento":"Classificação dos fatos contábeis: permutativos, modificativos e mistos.","macete":"Mexeu no valor do PL? Modificativo. Só trocou de lugar? Permutativo.","erroComum":"Achar que qualquer saída de caixa reduz o PL.","comoBancaPensa":"Item de base; a versão difícil traz o fato misto disfarçado."}},"CT-085":{"cognitivo":{"motivo":"Distingue os formatos de balancete pelo que cada um consegue evidenciar.","palavraCritica":"oito colunas"},"comentario":{"resolucao":"CERTO. O balancete de verificação varia conforme o detalhamento. O de DUAS colunas traz apenas os saldos finais devedores e credores; o de QUATRO acrescenta a movimentação do período a débito e a crédito; o de SEIS parte dos saldos anteriores, mostra a movimentação e chega aos saldos atuais; e o de OITO COLUNAS acrescenta a esses o SALDO DA MOVIMENTAÇÃO — o efeito líquido do período sobre cada conta, isolado do saldo que vinha de antes. É essa coluna adicional que permite ver, de relance, se o período aumentou ou reduziu o saldo da conta, sem ter de comparar o inicial com o final.","fundamento":"Balancete de verificação — formatos de 2, 4, 6 e 8 colunas.","macete":"Mais colunas, mais detalhe. Oito é o que isola o efeito líquido do período.","erroComum":"Tratar todo balancete como se fosse o de duas colunas.","comoBancaPensa":"Cobra o que cada formato evidencia, e não a definição de balancete."}},"CT-086":{"cognitivo":{"motivo":"Exige enxergar o valor CONTÁBIL LÍQUIDO, não o valor de aquisição.","palavraCritica":"totalmente depreciado ... sem valor residual"},"comentario":{"resolucao":"CERTO nas duas afirmações. Bem integralmente depreciado e sem valor residual tem VALOR CONTÁBIL LÍQUIDO ZERO: o custo de aquisição está inteiramente compensado pela depreciação acumulada. A baixa consiste em debitar a depreciação acumulada e creditar a conta do bem, pelo mesmo valor — não há ganho nem perda a reconhecer, e o resultado não é afetado. E o grupo do ativo também não muda de saldo, porque as duas contas envolvidas pertencem a ele e se anulam: uma retificadora diminui, a outra diminui na mesma medida. Só haveria efeito no resultado se restasse valor residual (gerando perda) ou se houvesse venda com contraprestação (gerando ganho).","fundamento":"Baixa de ativo imobilizado; valor contábil líquido.","macete":"Valor líquido zero: a baixa só apaga as duas pontas, sem passar pelo resultado.","erroComum":"Reconhecer perda pelo valor de aquisição, esquecendo a depreciação já acumulada.","comoBancaPensa":"Coloca as duas condições que zeram o valor contábil e testa quem raciocina pelo bruto."}},"CT-087":{"cognitivo":{"motivo":"Reconhecer o ponto: relatório para fins gerais — usuários externos.","palavraCritica":"priorizando os usuários internos"},"comentario":{"resolucao":"ERRADO. O relatório financeiro para fins gerais destina-se principalmente aos usuários externos que não podem exigir informações sob medida: investidores, credores por empréstimo e outros credores (CPC 00, itens 1.2 e 1.5). A administração tem acesso direto a informações internas e não é o usuário primário.","fundamento":"CPC 00 (R2) — Estrutura Conceitual, itens 1.2 a 1.10.","macete":"Fins gerais = usuário externo.","erroComum":"Achar que o relatório serve à gestão interna.","comoBancaPensa":"Troca o usuário primário."}},"CT-088":{"cognitivo":{"motivo":"Reconhecer o ponto: campo de aplicação — entidades sem fins lucrativos.","palavraCritica":"estão fora do campo de aplicação"},"comentario":{"resolucao":"ERRADO. O campo de aplicação da contabilidade alcança todas as entidades que possuem patrimônio, com ou sem fins lucrativos: empresas, entidades sociais, órgãos públicos. O que define a aplicação é a existência de patrimônio a controlar.","fundamento":"Doutrina contábil (campo de aplicação); ITG 2002 (entidades sem finalidade de lucros).","macete":"Tem patrimônio, tem contabilidade.","erroComum":"Restringir a contabilidade às empresas.","comoBancaPensa":"Exclui entidades do campo de aplicação."}},"CT-089":{"cognitivo":{"motivo":"Reconhecer o ponto: objetivos — estudo e controle do patrimônio.","palavraCritica":"estudo e o controle do patrimônio"},"comentario":{"resolucao":"CERTO. A contabilidade estuda e controla o patrimônio e suas variações, para fornecer informações úteis à tomada de decisão. É a definição clássica da disciplina.","fundamento":"Doutrina contábil (objetivo e finalidade).","macete":"Estudar e controlar o patrimônio.","erroComum":"Desconfiar da definição clássica.","comoBancaPensa":"Reproduz conceito básico."}},"CT-090":{"cognitivo":{"motivo":"Reconhecer o ponto: objeto — o patrimônio.","palavraCritica":"patrimônio da entidade"},"comentario":{"resolucao":"CERTO. O objeto da contabilidade é o patrimônio das entidades, isto é, o conjunto de bens, direitos e obrigações. Sobre ele recaem as técnicas de registro, demonstração, auditoria e análise.","fundamento":"Doutrina contábil (objeto).","macete":"Objeto = patrimônio.","erroComum":"Confundir objeto com objetivo.","comoBancaPensa":"Reproduz conceito básico."}},"CT-091":{"cognitivo":{"motivo":"Reconhecer o ponto: aspectos qualitativo e quantitativo.","palavraCritica":"aspecto qualitativo"},"comentario":{"resolucao":"ERRADO. A contabilidade estuda o patrimônio em seus aspectos qualitativo (natureza dos elementos: dinheiro, máquinas, dívidas) e quantitativo (valor monetário). Excluir o aspecto qualitativo contraria a definição.","fundamento":"Doutrina contábil (aspectos do patrimônio).","macete":"Patrimônio: qualidade + quantidade.","erroComum":"Achar que só importam os valores.","comoBancaPensa":"Restringe o objeto de estudo."}},"CT-092":{"cognitivo":{"motivo":"Reconhecer o ponto: técnicas contábeis — demonstrações incluídas.","palavraCritica":"exceto as demonstrações"},"comentario":{"resolucao":"ERRADO. As técnicas contábeis são escrituração, demonstrações contábeis, auditoria e análise de balanços. A elaboração das demonstrações a partir dos registros é técnica típica da contabilidade.","fundamento":"Doutrina contábil (técnicas: escrituração, demonstração, auditoria e análise).","macete":"Técnicas: E-D-A-A.","erroComum":"Esquecer as demonstrações entre as técnicas.","comoBancaPensa":"Exclui uma técnica."}},"CT-093":{"cognitivo":{"motivo":"Reconhecer o ponto: objetivo fundamental — 'a todos os interessados'.","palavraCritica":"a todos os interessados"},"comentario":{"resolucao":"ERRADO, segundo o gabarito. O objetivo é fornecer informações úteis à tomada de decisão dos usuários da informação contábil, e a Estrutura Conceitual define os usuários primários: investidores e credores. Falar em 'todos os interessados' generaliza o destinatário, e foi esse o ponto considerado errado.","fundamento":"CPC 00 (R2) — Estrutura Conceitual, itens 1.2 a 1.5.","macete":"Usuários primários: investidores e credores.","erroComum":"Aceitar a generalização do destinatário.","comoBancaPensa":"Amplia o destinatário para 'todos'."}},"CT-094":{"cognitivo":{"motivo":"Reconhecer o ponto: objeto na teoria atual — mais que propriedade.","palavraCritica":"de propriedade da entidade"},"comentario":{"resolucao":"CERTO. Na teoria atual, o patrimônio contábil abrange os recursos controlados pela entidade, ainda que não sejam de sua propriedade jurídica, como no arrendamento (direito de uso). O critério é o controle e os benefícios econômicos, não a propriedade.","fundamento":"CPC 00 (R2) — Estrutura Conceitual, item 4.3 e seguintes (ativo como recurso controlado); CPC 06 (R2).","macete":"Ativo: controle, não propriedade.","erroComum":"Associar ativo a título de propriedade.","comoBancaPensa":"Explora a primazia da essência sobre a forma."}},"CT-095":{"cognitivo":{"motivo":"Reconhecer o ponto: acompanhamento do patrimônio — coletar, sintetizar, registrar.","palavraCritica":"sintetizá-las e registrá-las"},"comentario":{"resolucao":"CERTO. Coletar, registrar e sintetizar informações são ações pelas quais a contabilidade acompanha de forma sistemática o patrimônio, que é seu objeto.","fundamento":"Doutrina contábil (funções da contabilidade).","macete":"Coleta, registro, síntese.","erroComum":"Desconfiar de item descritivo.","comoBancaPensa":"Reproduz as funções."}},"CT-096":{"cognitivo":{"motivo":"Reconhecer o ponto: razão de ser — informação útil.","palavraCritica":"informações úteis"},"comentario":{"resolucao":"CERTO. Oferecer aos agentes econômicos informações úteis para suas decisões é o objetivo fundamental da contabilidade moderna. Observação: no caderno o professor não circulou o gabarito; a anotação 'objetivo fundamental' indica CERTO, coerente com os itens vizinhos.","fundamento":"CPC 00 (R2) — Estrutura Conceitual, item 1.2.","macete":"Razão de ser: informação útil para decidir.","erroComum":"Confundir com controle fiscal.","comoBancaPensa":"Reproduz o objetivo."}},"CT-097":{"cognitivo":{"motivo":"Reconhecer o ponto: objetivo fundamental x controle do patrimônio.","palavraCritica":"controlar o patrimônio"},"comentario":{"resolucao":"ERRADO. Na alternativa correta da questão original, o objetivo fundamental da contabilidade é fornecer informações úteis aos usuários para a tomada de decisão. O controle do patrimônio é meio, não o objetivo fundamental.","fundamento":"CPC 00 (R2) — Estrutura Conceitual, item 1.2.","macete":"Fim: informação para decidir.","erroComum":"Tratar o meio como fim.","comoBancaPensa":"Troca o objetivo pelo instrumento."}},"CT-098":{"cognitivo":{"motivo":"Reconhecer o ponto: concepção contemporânea — informação relevante.","palavraCritica":"informações relevantes"},"comentario":{"resolucao":"CERTO. Na concepção contemporânea, a contabilidade é um sistema de informação, e seu objetivo principal é fornecer informações relevantes à decisão dos usuários.","fundamento":"CPC 00 (R2) — Estrutura Conceitual, itens 1.2 e 2.6.","macete":"Contabilidade = sistema de informação.","erroComum":"Desconfiar de item correto.","comoBancaPensa":"Reproduz o conceito."}},"CT-099":{"cognitivo":{"motivo":"Reconhecer o ponto: contabilidade aplicada.","palavraCritica":"contabilidade industrial"},"comentario":{"resolucao":"CERTO. Contabilidade aplicada é a teoria contábil adaptada a ramos específicos: industrial (custos), pública, bancária, rural, hospitalar, entre outras.","fundamento":"Doutrina contábil (ramos da contabilidade).","macete":"Teoria geral + ramo = aplicada.","erroComum":"Confundir com contabilidade geral.","comoBancaPensa":"Reproduz o conceito."}},"CT-100":{"cognitivo":{"motivo":"Reconhecer o ponto: técnicas cada vez mais sofisticadas.","palavraCritica":"técnicas cada vez mais sofisticadas"},"comentario":{"resolucao":"CERTO. Para registrar, estimar, organizar e sintetizar dados num ambiente econômico complexo, a contabilidade emprega técnicas cada vez mais elaboradas, como estimativas, valor justo e sistemas integrados.","fundamento":"Doutrina contábil.","macete":"Mais complexidade, mais técnica.","erroComum":"Desconfiar por soar genérico.","comoBancaPensa":"Reproduz ideia doutrinária."}},"CT-101":{"cognitivo":{"motivo":"Reconhecer o ponto: contabilidade como ciência social.","palavraCritica":"ciência social"},"comentario":{"resolucao":"CERTO. A contabilidade é ciência social: estuda e controla o patrimônio das entidades para fornecer informações sobre sua composição e variações, úteis ao tomador de decisão.","fundamento":"Doutrina contábil.","macete":"Ciência SOCIAL do patrimônio.","erroComum":"Classificá-la como ciência exata.","comoBancaPensa":"Reproduz a definição."}},"CT-102":{"cognitivo":{"motivo":"Reconhecer o ponto: objeto ≠ registro dos eventos.","palavraCritica":"registro dos eventos"},"comentario":{"resolucao":"ERRADO. Na alternativa correta da questão original, o objeto da contabilidade é o patrimônio das entidades. O registro dos eventos é técnica (escrituração), não o objeto.","fundamento":"Doutrina contábil (objeto).","macete":"Objeto = patrimônio; registro = técnica.","erroComum":"Confundir objeto e técnica.","comoBancaPensa":"Troca o objeto pela técnica."}},"CT-103":{"cognitivo":{"motivo":"Reconhecer o ponto: finalidades — controle do patrimônio e tributos.","palavraCritica":"apurar os tributos"},"comentario":{"resolucao":"ERRADO. Controlar o patrimônio É finalidade da contabilidade, e apurar tributos não é sua função principal, mas uma das aplicações da informação contábil. Na questão original, só era correta a afirmação de que o principal objetivo inclui fornecer informação útil ao usuário.","fundamento":"Doutrina contábil (finalidades).","macete":"Controle do patrimônio: sim. Tributo: não é o principal.","erroComum":"Reduzir a contabilidade ao fisco.","comoBancaPensa":"Junta duas afirmações falsas."}},"CT-104":{"cognitivo":{"motivo":"Reconhecer o ponto: objetivo — usuários internos e externos.","palavraCritica":"determinado grupo de usuários"},"comentario":{"resolucao":"ERRADO. Na alternativa correta da questão original, o principal objetivo é fornecer informações úteis à decisão de seus diversos usuários, internos e externos. Demonstrações com finalidade específica para um grupo não são o objetivo principal.","fundamento":"CPC 00 (R2) — Estrutura Conceitual, item 1.2.","macete":"Usuários diversos, internos e externos.","erroComum":"Restringir a um grupo.","comoBancaPensa":"Restringe o destinatário."}},"CT-105":{"cognitivo":{"motivo":"Reconhecer o ponto: escola patrimonialista.","palavraCritica":"patrimonialista"},"comentario":{"resolucao":"CERTO. A concepção da contabilidade como ciência do patrimônio é da escola patrimonialista, de Vincenzo Masi, que adotou o patrimônio como objeto. Contista, personalista e aziendalista são escolas anteriores, com outros enfoques.","fundamento":"História do pensamento contábil (escolas contábeis).","macete":"Patrimônio → patrimonialista (Masi).","erroComum":"Confundir com a aziendalista.","comoBancaPensa":"Cobra o nome da escola."}},"CT-106":{"cognitivo":{"motivo":"Reconhecer o ponto: vincenzo Masi — objeto.","palavraCritica":"a azienda"},"comentario":{"resolucao":"ERRADO. Vincenzo Masi, fundador do patrimonialismo, identificou o PATRIMÔNIO como objeto da contabilidade. A azienda é o enfoque da escola aziendalista, de Gino Zappa.","fundamento":"História do pensamento contábil.","macete":"Masi = patrimônio; Zappa = azienda.","erroComum":"Trocar os autores.","comoBancaPensa":"Troca o objeto da escola."}},"CT-107":{"cognitivo":{"motivo":"Reconhecer o ponto: cálculo do passivo com prejuízo.","palavraCritica":"13,8 milhões"},"comentario":{"resolucao":"CERTO. Patrimônio líquido final = 350 mil − 650 mil = −300 mil. Pela equação A = P + PL, P = A − PL = 13,5 milhões − (−0,3 milhão) = 13,8 milhões.","fundamento":"Equação fundamental do patrimônio (A = P + PL).","macete":"PL negativo soma ao passivo.","erroComum":"Esquecer o sinal do PL.","comoBancaPensa":"Testa conta com PL negativo."}},"CT-108":{"cognitivo":{"motivo":"Reconhecer o ponto: situação líquida negativa.","palavraCritica":"positiva em R$ 10.600"},"comentario":{"resolucao":"ERRADO. Ativo = caixa 12.000 + estoques 27.000 + imobilizado 36.000 − depreciação acumulada 3.600 = 71.400. Passivo = fornecedores 38.000 + empréstimos de longo prazo 44.000 = 82.000. Situação líquida = 71.400 − 82.000 = −10.600, ou seja, NEGATIVA.","fundamento":"Equação fundamental do patrimônio.","macete":"SL = A − P.","erroComum":"Somar a depreciação acumulada ao ativo.","comoBancaPensa":"Inverte o sinal da resposta."}},"CT-109":{"cognitivo":{"motivo":"Reconhecer o ponto: passivo a descoberto — conceito.","palavraCritica":"o passivo é insuficiente"},"comentario":{"resolucao":"ERRADO. No passivo a descoberto, é o ATIVO que é insuficiente para cobrir o passivo: PL negativo, A < P. Por isso a soma, em módulo, do ativo com o PL iguala o passivo (alternativa correta da questão original).","fundamento":"Equação fundamental do patrimônio (situações líquidas).","macete":"Passivo a descoberto: A < P.","erroComum":"Inverter quem é insuficiente.","comoBancaPensa":"Troca os sujeitos."}},"CT-110":{"cognitivo":{"motivo":"Reconhecer o ponto: passivo a descoberto — ativo insuficiente.","palavraCritica":"ativo é insuficiente"},"comentario":{"resolucao":"CERTO. Há passivo a descoberto quando o ativo não basta para cobrir as obrigações com terceiros: A < P, logo PL negativo.","fundamento":"Equação fundamental do patrimônio.","macete":"PL < 0 = passivo a descoberto.","erroComum":"Inverter os termos.","comoBancaPensa":"Reproduz o conceito."}},"CT-111":{"cognitivo":{"motivo":"Reconhecer o ponto: equação fundamental — ativo.","palavraCritica":"equação fundamental"},"comentario":{"resolucao":"CERTO. A equação fundamental do patrimônio é Ativo = Passivo + Patrimônio Líquido. O ativo é um de seus componentes.","fundamento":"Equação fundamental do patrimônio.","macete":"A = P + PL.","erroComum":"Desconfiar de item óbvio.","comoBancaPensa":"Reproduz conceito básico."}},"CT-112":{"cognitivo":{"motivo":"Reconhecer o ponto: patrimônio como objeto distintivo.","palavraCritica":"objeto de estudo"},"comentario":{"resolucao":"CERTO. O que distingue a contabilidade de outras ciências ligadas à gestão (administração, economia) é ter o patrimônio das entidades como objeto de estudo.","fundamento":"Doutrina contábil (objeto).","macete":"Objeto próprio: patrimônio.","erroComum":"Desconfiar de item conceitual.","comoBancaPensa":"Reproduz conceito."}},"CT-113":{"cognitivo":{"motivo":"Reconhecer o ponto: sem patrimônio, sem entidade contábil.","palavraCritica":"sem patrimônio"},"comentario":{"resolucao":"CERTO. Para a ciência contábil, a entidade contábil se define pelo patrimônio. Sem patrimônio, não há o que registrar nem controlar.","fundamento":"Doutrina contábil; Resolução CFC 750/1993 (princípio da entidade, revogada, mas referida pela doutrina).","macete":"Entidade contábil pressupõe patrimônio.","erroComum":"Confundir com personalidade jurídica.","comoBancaPensa":"Cobra a noção de entidade."}},"CT-114":{"cognitivo":{"motivo":"Reconhecer o ponto: patrimônio — ativo e passivo.","palavraCritica":"apenas pelos grupos do ativo"},"comentario":{"resolucao":"ERRADO. O patrimônio é o conjunto de bens, direitos e obrigações. Nas demonstrações, é representado pelo ativo, pelo passivo e pelo patrimônio líquido, e não só pelo ativo.","fundamento":"Equação fundamental do patrimônio; Lei 6.404/1976, art. 178.","macete":"Patrimônio = A, P e PL.","erroComum":"Excluir as obrigações do patrimônio.","comoBancaPensa":"Restringe o conceito."}},"CT-115":{"cognitivo":{"motivo":"Reconhecer o ponto: mudança de destinação dos bens.","palavraCritica":"prejudica a classificação uniforme"},"comentario":{"resolucao":"ERRADO. Aplicar recursos em bens de longo prazo ou não essenciais à atividade não 'prejudica' a classificação. A Lei 6.404 e os CPCs a determinam pela destinação de cada elemento: investimentos, imobilizado, intangível. A mudança de destinação gera reclassificação, não divergência de natureza.","fundamento":"Lei 6.404/1976, art. 179.","macete":"Classifica-se pela destinação.","erroComum":"Achar que o uso diverso desorganiza o balanço.","comoBancaPensa":"Usa linguagem rebuscada para disfarçar ideia errada."}},"CT-116":{"cognitivo":{"motivo":"Reconhecer o ponto: pL e reservas de reavaliação.","palavraCritica":"Reservas de Reavaliação"},"comentario":{"resolucao":"ERRADO. A diferença entre aplicações (ativo) e origens de terceiros (passivo) é o patrimônio líquido, mas a lista de contas do item inclui 'reservas de reavaliação', que a Lei 11.638/2007 eliminou para novas constituições. A composição atual do PL é capital social, reservas de capital, ajustes de avaliação patrimonial, reservas de lucros, ações em tesouraria e prejuízos acumulados (art. 178, § 2º, III).","fundamento":"Lei 6.404/1976, art. 178, § 2º, III, com a redação da Lei 11.638/2007.","macete":"PL hoje: sem reserva de reavaliação.","erroComum":"Usar a lista antiga do PL.","comoBancaPensa":"Esconde uma conta extinta numa lista longa."}},"CT-117":{"cognitivo":{"motivo":"Reconhecer o ponto: bens que produzem bens não viram 'capital'.","palavraCritica":"denominação de capital"},"comentario":{"resolucao":"ERRADO. Bens usados para produzir outros bens continuam no ativo (imobilizado, estoques). Capital é termo do patrimônio líquido (capital social) ou da origem de recursos. A produção não muda a natureza de ativo dos bens.","fundamento":"Doutrina contábil; Lei 6.404/1976, arts. 178 e 179.","macete":"Bem produtivo continua ativo.","erroComum":"Confundir 'capital' econômico com conta do PL.","comoBancaPensa":"Mistura vocabulário econômico e contábil."}},"CT-118":{"cognitivo":{"motivo":"Reconhecer o ponto: patrimônio — elementos negativos não são despesas.","palavraCritica":"despesas totais"},"comentario":{"resolucao":"ERRADO. Os elementos negativos do patrimônio são as obrigações com terceiros (passivo). Despesas são contas de resultado, e não componentes do patrimônio. Perdas reduzem o PL, mas não figuram como 'elemento negativo' ao lado das obrigações.","fundamento":"Equação fundamental do patrimônio; CPC 00 (R2), cap. 4.","macete":"Negativo do patrimônio = obrigações.","erroComum":"Pôr despesas no patrimônio.","comoBancaPensa":"Insere conta de resultado no patrimônio."}},"CT-119":{"cognitivo":{"motivo":"Reconhecer o ponto: fontes de financiamento — próprias e de terceiros.","palavraCritica":"duas fontes de financiamento"},"comentario":{"resolucao":"CERTO. Passivo e PL são as origens dos recursos aplicados no ativo. O capital próprio (PL), modificado pelos resultados, é a parcela dos proprietários. O capital de terceiros vem da captação no mercado.","fundamento":"Equação fundamental do patrimônio (origens e aplicações).","macete":"Origens: próprio (PL) + terceiros (P).","erroComum":"Achar que só o passivo financia o ativo.","comoBancaPensa":"Reproduz a lógica das origens."}},"CT-120":{"cognitivo":{"motivo":"Reconhecer o ponto: competência x caixa.","palavraCritica":"regime de caixa"},"comentario":{"resolucao":"ERRADO. O regime que considera todos os eventos que afetam o resultado do exercício, independentemente de recebimento ou pagamento, é o de COMPETÊNCIA. O de caixa considera só entradas e saídas de dinheiro.","fundamento":"CPC 00 (R2) — Estrutura Conceitual, itens 1.17 e 1.18; CPC 26, item 27.","macete":"Competência: fato gerador. Caixa: dinheiro.","erroComum":"Trocar os nomes.","comoBancaPensa":"Troca o rótulo."}},"CT-121":{"cognitivo":{"motivo":"Reconhecer o ponto: competência — receita na entrega.","palavraCritica":"somente no momento do recebimento"},"comentario":{"resolucao":"ERRADO. Pelo regime de competência, a receita de vendas é reconhecida quando ocorre o fato gerador (entrega do bem ou serviço, satisfação da obrigação de desempenho, CPC 47), independentemente do recebimento.","fundamento":"CPC 47; CPC 00 (R2), item 1.17.","macete":"Receita: na entrega, não no recebimento.","erroComum":"Aplicar a lógica de caixa.","comoBancaPensa":"Descreve o regime de caixa sob o nome de competência."}},"CT-122":{"cognitivo":{"motivo":"Reconhecer o ponto: lucro por competência.","palavraCritica":"lucro de R$ 15.000"},"comentario":{"resolucao":"CERTO. Por competência, considera-se o que foi vendido (125.000) e a despesa incorrida (110.000), sem olhar recebimentos e pagamentos: 125.000 − 110.000 = 15.000. Por caixa, seria 115.000 − 108.000 = 7.000.","fundamento":"CPC 00 (R2), item 1.17.","macete":"Competência: vendeu − incorreu.","erroComum":"Usar valores recebidos e pagos.","comoBancaPensa":"Põe dados de caixa para distrair."}},"CT-123":{"cognitivo":{"motivo":"Reconhecer o ponto: competência — receita independe do recebimento.","palavraCritica":"apenas no momento do recebimento"},"comentario":{"resolucao":"ERRADO. Na competência, as receitas são reconhecidas quando realizadas (fato gerador), independentemente do recebimento.","fundamento":"CPC 00 (R2), item 1.17.","macete":"Competência ≠ recebimento.","erroComum":"Confundir com caixa.","comoBancaPensa":"Usa 'apenas' para descrever o regime de caixa."}},"CT-124":{"cognitivo":{"motivo":"Reconhecer o ponto: competência — despesa quando ocorre.","palavraCritica":"independentemente do fluxo de caixa"},"comentario":{"resolucao":"CERTO. Pelo regime de competência, a despesa é reconhecida quando incorrida, independentemente do pagamento.","fundamento":"CPC 00 (R2), item 1.17.","macete":"Despesa: quando incorrida.","erroComum":"Desconfiar do item correto.","comoBancaPensa":"Reproduz o conceito."}},"CT-125":{"cognitivo":{"motivo":"Reconhecer o ponto: dFC é exceção à competência.","palavraCritica":"todas as suas demonstrações"},"comentario":{"resolucao":"ERRADO. A entidade elabora suas demonstrações pelo regime de competência, EXCETO a demonstração dos fluxos de caixa (CPC 26, item 27). Na questão original, a alternativa correta tratava da fidedignidade da informação pelo regime de competência.","fundamento":"CPC 26 (R1), item 27; CPC 03.","macete":"Competência em tudo, menos na DFC.","erroComum":"Esquecer a exceção da DFC.","comoBancaPensa":"Usa 'todas' para apagar a exceção."}},"CT-126":{"cognitivo":{"motivo":"Reconhecer o ponto: lucro pelo regime de caixa.","palavraCritica":"R$ 84 mil"},"comentario":{"resolucao":"CERTO. Pelo regime de caixa, contam as entradas e saídas ligadas ao resultado: serviços à vista 100, salários pagos (−30), antecipação recebida (+15) e energia paga (−1) = 84 mil. A consultoria a prazo não saiu do caixa, e o empréstimo a funcionários não é despesa. Por competência, o lucro seria 100 − 5 − 1 = 94 mil.","fundamento":"Regimes de caixa e de competência; CPC 00 (R2), item 1.17.","macete":"Caixa: o que entrou e saiu.","erroComum":"Somar a consultoria ou o empréstimo.","comoBancaPensa":"Mistura eventos de caixa e de competência."}},"CT-127":{"cognitivo":{"motivo":"Reconhecer o ponto: competência — receita sem dinheiro.","palavraCritica":"depende do recebimento"},"comentario":{"resolucao":"ERRADO. No regime de competência, o registro da receita não depende do recebimento em dinheiro.","fundamento":"CPC 00 (R2), item 1.17.","macete":"Competência ignora o caixa.","erroComum":"Confundir os regimes.","comoBancaPensa":"Cria uma condição de caixa."}},"CT-128":{"cognitivo":{"motivo":"Reconhecer o ponto: competência — visão fiel.","palavraCritica":"visão fiel"},"comentario":{"resolucao":"CERTO. Ao confrontar receitas e despesas do período em que ocorrem, o regime de competência dá visão mais fiel da posição patrimonial e do desempenho do que o regime de caixa (CPC 00, item 1.17).","fundamento":"CPC 00 (R2), itens 1.17 e 1.18.","macete":"Competência = desempenho real.","erroComum":"Desconfiar do elogio.","comoBancaPensa":"Reproduz a justificativa da norma."}},"CT-129":{"cognitivo":{"motivo":"Reconhecer o ponto: competência — todas as empresas.","palavraCritica":"somente a empresas de grande porte"},"comentario":{"resolucao":"ERRADO. O regime de competência é obrigatório para todas as entidades, inclusive pequenas e médias (NBC TG 1000, CPC PME). Não há restrição por porte.","fundamento":"NBC TG 1000 (PME); CPC 00 (R2).","macete":"Competência vale para todos.","erroComum":"Achar que pequena empresa usa caixa.","comoBancaPensa":"Restringe por porte."}},"CT-130":{"cognitivo":{"motivo":"Reconhecer o ponto: folha de dezembro paga em janeiro.","palavraCritica":"primeiros dias de dezembro/X0"},"comentario":{"resolucao":"ERRADO. A folha de dezembro/X0 é despesa de dezembro (competência), mas o pagamento ocorre nos primeiros dias do mês SEGUINTE (janeiro/X1). O item põe o pagamento no próprio dezembro.","fundamento":"CPC 00 (R2), item 1.17.","macete":"Despesa no mês trabalhado; pagamento no seguinte.","erroComum":"Ler rápido a data do pagamento.","comoBancaPensa":"Troca o mês do pagamento."}},"CT-131":{"cognitivo":{"motivo":"Reconhecer o ponto: desconto obtido — receita financeira.","palavraCritica":"receita financeira"},"comentario":{"resolucao":"CERTO. O desconto obtido pela quitação antecipada é receita financeira, reconhecida na data em que ocorre (quitação), pelo regime de competência.","fundamento":"CPC 00 (R2), item 1.17; Lei 6.404/1976, art. 187.","macete":"Desconto obtido = receita financeira.","erroComum":"Tratá-lo como redução de custo.","comoBancaPensa":"Cobra classificação e momento."}},"CT-132":{"cognitivo":{"motivo":"Reconhecer o ponto: receita na prestação do serviço.","palavraCritica":"novembro de 2019"},"comentario":{"resolucao":"ERRADO. A receita é reconhecida quando o serviço é prestado, em dezembro de 2019. O adiantamento recebido em novembro é passivo (adiantamento de clientes) até a prestação.","fundamento":"CPC 47; CPC 00 (R2).","macete":"Adiantamento = passivo até prestar.","erroComum":"Reconhecer receita no recebimento.","comoBancaPensa":"Usa a data do adiantamento."}},"CT-133":{"cognitivo":{"motivo":"Reconhecer o ponto: lucro por competência — classificação dos eventos.","palavraCritica":"lucro de R$ 90.000"},"comentario":{"resolucao":"CERTO. Receitas realizadas (competência) = 180.000 (realizadas e não recebidas) + 90.000 (realizadas e recebidas) = 270.000. Despesas incorridas = 100.000 (incorridas e pagas) + 80.000 (incorridas e não pagas) = 180.000. Lucro = 90.000. Receitas recebidas antecipadamente e despesas pagas antecipadamente não entram no resultado.","fundamento":"CPC 00 (R2), item 1.17.","macete":"Competência: realizadas − incorridas.","erroComum":"Incluir antecipações.","comoBancaPensa":"Mistura valores de caixa."}},"CT-134":{"cognitivo":{"motivo":"Reconhecer o ponto: aluguel antecipado — despesa antecipada.","palavraCritica":"despesas antecipadas"},"comentario":{"resolucao":"CERTO. O aluguel pago antecipadamente é um direito (ativo, despesas antecipadas) e vai sendo apropriado mensalmente como despesa, à medida que o período de uso transcorre (competência).","fundamento":"CPC 00 (R2); Lei 6.404/1976, art. 179, I.","macete":"Pagou antes de usar: ativo; usou: despesa.","erroComum":"Lançar tudo como despesa no pagamento.","comoBancaPensa":"Reproduz a contabilização correta."}},"CT-135":{"cognitivo":{"motivo":"Reconhecer o ponto: plano de contas não é livro obrigatório.","palavraCritica":"livros contábeis obrigatórios"},"comentario":{"resolucao":"ERRADO. O plano de contas é instrumento interno de organização, não livro obrigatório, e não é registrado na junta comercial. Livros obrigatórios são o Diário (CC, art. 1.180) e outros exigidos por lei especial.","fundamento":"CC, arts. 1.179 a 1.181.","macete":"Plano de contas: guia interno.","erroComum":"Tratá-lo como livro.","comoBancaPensa":"Atribui natureza de livro ao plano."}},"CT-136":{"cognitivo":{"motivo":"Reconhecer o ponto: compra de terreno — débito e crédito invertidos.","palavraCritica":"a débito na conta bancos"},"comentario":{"resolucao":"ERRADO. Na compra à vista, debita-se terrenos (aumento de ativo, aplicação) e credita-se bancos (redução de ativo, origem). O item inverte os lançamentos.","fundamento":"Método das partidas dobradas.","macete":"Entrou bem: débito. Saiu dinheiro: crédito.","erroComum":"Inverter débito e crédito.","comoBancaPensa":"Inverte o lançamento."}},"CT-137":{"cognitivo":{"motivo":"Reconhecer o ponto: plano de contas — mais que o rol.","palavraCritica":"composto completamente pelo rol"},"comentario":{"resolucao":"ERRADO. O plano de contas completo tem o elenco (rol) de contas e também o manual: função, funcionamento e forma de escrituração de cada conta. O rol é só uma parte.","fundamento":"Doutrina contábil (plano de contas).","macete":"Plano = elenco + manual.","erroComum":"Confundir plano com elenco.","comoBancaPensa":"Reduz o plano ao elenco."}},"CT-138":{"cognitivo":{"motivo":"Reconhecer o ponto: lucros acumulados é conta do PL.","palavraCritica":"conta de lucros acumulados"},"comentario":{"resolucao":"ERRADO. Receitas e despesas são contas de resultado, mas lucros (ou prejuízos) acumulados é conta patrimonial do PL, que recebe o resultado apurado.","fundamento":"Lei 6.404/1976, art. 178, § 2º, III.","macete":"Lucros acumulados: PL.","erroComum":"Pôr lucros acumulados no resultado.","comoBancaPensa":"Junta conta do PL às de resultado."}},"CT-139":{"cognitivo":{"motivo":"Reconhecer o ponto: contas redutoras — natureza oposta.","palavraCritica":"natureza diversa"},"comentario":{"resolucao":"CERTO. Contas redutoras (retificadoras) têm natureza oposta à do grupo em que estão. Exemplos: depreciação acumulada (credora) no ativo e ações em tesouraria (devedora) no PL.","fundamento":"Doutrina contábil (contas retificadoras).","macete":"Retificadora = natureza oposta.","erroComum":"Achar que acompanham o grupo.","comoBancaPensa":"Reproduz o conceito."}},"CT-140":{"cognitivo":{"motivo":"Reconhecer o ponto: natureza dos saldos.","palavraCritica":"podem apresentar saldo credor ou devedor"},"comentario":{"resolucao":"CERTO. Contas do ativo têm natureza devedora. Contas de resultado podem ser devedoras (despesas) ou credoras (receitas).","fundamento":"Doutrina contábil (natureza das contas).","macete":"Ativo: devedor. Resultado: depende.","erroComum":"Achar que resultado é sempre credor.","comoBancaPensa":"Reproduz o conceito."}},"CT-141":{"cognitivo":{"motivo":"Reconhecer o ponto: ativo e passivo têm contas devedoras e credoras.","palavraCritica":"tanto por contas devedoras quanto por contas credoras"},"comentario":{"resolucao":"CERTO. Por causa das retificadoras, o ativo tem contas credoras (depreciação acumulada, PECLD) e o passivo pode ter contas devedoras (encargos a transcorrer, juros a apropriar).","fundamento":"Doutrina contábil (contas retificadoras).","macete":"Retificadoras misturam naturezas.","erroComum":"Achar que o grupo tem natureza única.","comoBancaPensa":"Explora as retificadoras."}},"CT-142":{"cognitivo":{"motivo":"Reconhecer o ponto: classificação das contas — sintéticas e analíticas.","palavraCritica":"circulantes e não circulantes"},"comentario":{"resolucao":"ERRADO, segundo o gabarito. Quanto ao nível de detalhamento no plano de contas, as contas classificam-se em sintéticas e analíticas. Circulante e não circulante é critério de grupos do balanço, não classificação geral das contas, que incluem também as de resultado.","fundamento":"Doutrina contábil (plano de contas).","macete":"Plano de contas: sintética x analítica.","erroComum":"Usar critério do balanço para todas as contas.","comoBancaPensa":"Troca o critério de classificação."}},"CT-143":{"cognitivo":{"motivo":"Reconhecer o ponto: funcionamento x função da conta.","palavraCritica":"finalidade dessa conta"},"comentario":{"resolucao":"ERRADO. Dizer como a conta aumenta e diminui (crédito e débito) é descrever seu FUNCIONAMENTO. A função ou finalidade diz o que a conta registra.","fundamento":"Doutrina contábil (manual de contas).","macete":"Como movimenta = funcionamento.","erroComum":"Trocar função e funcionamento.","comoBancaPensa":"Troca os conceitos do manual."}},"CT-144":{"cognitivo":{"motivo":"Reconhecer o ponto: função e funcionamento preteridos na prática.","palavraCritica":"costumam ser preteridas"},"comentario":{"resolucao":"CERTO, segundo a banca. Embora sejam peças essenciais do plano de contas, as descrições de função e funcionamento das contas costumam ser negligenciadas na prática brasileira, que se limita ao elenco de contas.","fundamento":"Doutrina contábil (plano de contas).","macete":"Na prática, muito elenco e pouco manual.","erroComum":"Achar que o item é teórico demais para ser certo.","comoBancaPensa":"Cobra constatação doutrinária."}},"CT-145":{"cognitivo":{"motivo":"Reconhecer o ponto: despesas antecipadas são ativo.","palavraCritica":"conta de resultado"},"comentario":{"resolucao":"ERRADO. Despesas antecipadas são conta de ATIVO, que registra recursos aplicados em gastos a serem reconhecidos no resultado de períodos futuros (alternativa correta da questão original). Só viram despesa quando incorridas.","fundamento":"Lei 6.404/1976, art. 179, I; CPC 00 (R2).","macete":"Pagou e não usou: ativo.","erroComum":"Classificar como resultado.","comoBancaPensa":"Troca o grupo da conta."}},"CT-146":{"cognitivo":{"motivo":"Reconhecer o ponto: plano de contas — foco nos usuários da informação.","palavraCritica":"pessoal da contabilidade"},"comentario":{"resolucao":"ERRADO. Um bom plano de contas atende às necessidades de informação dos usuários (administração, investidores, fisco), e não só da equipe contábil. Focar apenas no setor de contabilidade restringe indevidamente sua finalidade.","fundamento":"Doutrina contábil (plano de contas).","macete":"Plano de contas serve aos usuários.","erroComum":"Pensá-lo só para o contador.","comoBancaPensa":"Restringe o destinatário."}},"CT-147":{"cognitivo":{"motivo":"Reconhecer o ponto: plano completo — função das contas.","palavraCritica":"a função da conta"},"comentario":{"resolucao":"CERTO. Além do elenco (nome, código), o plano de contas completo deve conter a função de cada conta, que é parte do manual.","fundamento":"Doutrina contábil (plano de contas).","macete":"Plano = elenco + função.","erroComum":"Achar que codificação basta.","comoBancaPensa":"Cobra o elemento que diferencia plano de elenco."}},"CT-148":{"cognitivo":{"motivo":"Reconhecer o ponto: classificação de contas — estoques e descontos.","palavraCritica":"estoques: passivo"},"comentario":{"resolucao":"ERRADO. Estoques são ativo e descontos obtidos são conta de resultado (receita financeira). A classificação correta da questão original era empréstimos a pagar no passivo, despesas de depreciação no resultado, veículos e estoques no ativo e descontos obtidos no resultado.","fundamento":"Lei 6.404/1976, arts. 178 e 187.","macete":"Estoque = ativo; desconto obtido = resultado.","erroComum":"Pôr desconto obtido no ativo.","comoBancaPensa":"Troca o grupo de duas contas."}},"CT-149":{"cognitivo":{"motivo":"Reconhecer o ponto: natureza devedora — receita de vendas não.","palavraCritica":"receita de vendas"},"comentario":{"resolucao":"ERRADO. Despesas com salários e máquinas e equipamentos são devedoras, mas receita de vendas tem natureza CREDORA. Na questão original, eram devedoras caixa, contas a receber e máquinas e equipamentos.","fundamento":"Doutrina contábil (natureza das contas).","macete":"Receita: credora.","erroComum":"Achar que toda conta de resultado é devedora.","comoBancaPensa":"Mistura uma credora entre devedoras."}},"CT-150":{"cognitivo":{"motivo":"Reconhecer o ponto: classificação de contas — correta.","palavraCritica":"fornecedores: passivo"},"comentario":{"resolucao":"CERTO. Despesas de pessoal e receita de vendas são de resultado; imóveis e caixa são ativo; fornecedores são passivo. É a alternativa correta da questão original.","fundamento":"Lei 6.404/1976, arts. 178 e 187.","macete":"Bens e dinheiro: ativo; dívidas: passivo; receitas e despesas: resultado.","erroComum":"Pôr despesa no ativo.","comoBancaPensa":"Reproduz a classificação correta."}},"CT-151":{"cognitivo":{"motivo":"Reconhecer o ponto: natureza credora.","palavraCritica":"receita de vendas"},"comentario":{"resolucao":"CERTO. Empréstimos a pagar e salários a pagar (passivo) e receita de vendas (resultado credor) são contas de natureza credora.","fundamento":"Doutrina contábil (natureza das contas).","macete":"Passivo, PL e receitas: credoras.","erroComum":"Confundir salários a pagar com despesa.","comoBancaPensa":"Reproduz a alternativa correta."}},"CT-152":{"cognitivo":{"motivo":"Reconhecer o ponto: elenco não basta.","palavraCritica":"basta o elenco de contas"},"comentario":{"resolucao":"ERRADO. Para ser completo, o plano de contas deve conter pelo menos o elenco e a função das contas (alternativa correta da questão original). O elenco sozinho não basta.","fundamento":"Doutrina contábil (plano de contas).","macete":"Elenco sozinho não é plano completo.","erroComum":"Confundir plano e elenco.","comoBancaPensa":"Reduz o mínimo exigido."}},"CT-153":{"cognitivo":{"motivo":"Reconhecer o ponto: ajustes de avaliação patrimonial — saldo duplo.","palavraCritica":"ajustes de avaliação patrimonial"},"comentario":{"resolucao":"CERTO. Os ajustes de avaliação patrimonial registram aumentos e diminuições de valor (valor justo) ainda não realizados no resultado. Por isso podem ter saldo credor ou devedor (Lei 6.404, art. 182, § 3º).","fundamento":"Lei 6.404/1976, art. 182, § 3º.","macete":"AAP: saldo pode ser credor ou devedor.","erroComum":"Achar que toda conta do PL é credora.","comoBancaPensa":"Cobra a conta de saldo bivalente."}},"CT-154":{"cognitivo":{"motivo":"Reconhecer o ponto: equação contábil completa.","palavraCritica":"ativos = passivos"},"comentario":{"resolucao":"ERRADO. Pelas partidas dobradas, a soma dos débitos iguala a dos créditos, o que se reflete na equação Ativo = Passivo + Patrimônio Líquido, e não 'ativos = passivos'. Na questão original, a alternativa correta dizia que o método facilita a detecção de erros e fraudes.","fundamento":"Método das partidas dobradas; equação fundamental do patrimônio.","macete":"A = P + PL.","erroComum":"Esquecer o PL.","comoBancaPensa":"Omite um termo da equação."}},"CT-155":{"cognitivo":{"motivo":"Reconhecer o ponto: partidas dobradas é método, não técnica.","palavraCritica":"técnicas da ciência contábil"},"comentario":{"resolucao":"ERRADO, segundo o gabarito. As técnicas contábeis são escrituração, demonstrações, auditoria e análise. As partidas dobradas são o MÉTODO de escrituração, não uma técnica autônoma.","fundamento":"Doutrina contábil.","macete":"Partidas dobradas = método de escrituração.","erroComum":"Confundir método e técnica.","comoBancaPensa":"Troca o rótulo."}},"CT-156":{"cognitivo":{"motivo":"Reconhecer o ponto: método de Veneza é o usual.","palavraCritica":"partidas simples"},"comentario":{"resolucao":"ERRADO. O método de Veneza (partidas dobradas) é o adotado universalmente na escrituração contábil. As partidas simples servem só a controles auxiliares.","fundamento":"Método das partidas dobradas.","macete":"Veneza = partidas dobradas = padrão.","erroComum":"Não reconhecer o sinônimo.","comoBancaPensa":"Inverte o método usual."}},"CT-157":{"cognitivo":{"motivo":"Reconhecer o ponto: lançamentos simultâneos e antitéticos.","palavraCritica":"antitéticos de igual valor"},"comentario":{"resolucao":"CERTO. No método das partidas dobradas, cada fato gera lançamentos simultâneos, a débito e a crédito (antitéticos), de igual valor, num sistema fechado em que débitos e créditos se equilibram.","fundamento":"Método das partidas dobradas.","macete":"D = C, sempre.","erroComum":"Estranhar o vocabulário.","comoBancaPensa":"Usa termos técnicos corretos."}},"CT-158":{"cognitivo":{"motivo":"Reconhecer o ponto: pacioli divulgou, não inventou.","palavraCritica":"inventou"},"comentario":{"resolucao":"ERRADO. Luca Pacioli DIVULGOU e sistematizou o método das partidas dobradas, já usado por mercadores italianos, no tratado 'Particularis de Computis et Scripturis', parte da Summa de Arithmetica (1494). Não foi o inventor.","fundamento":"História da contabilidade.","macete":"Pacioli divulgou.","erroComum":"Atribuir a invenção a Pacioli.","comoBancaPensa":"Troca divulgar por inventar."}},"CT-159":{"cognitivo":{"motivo":"Reconhecer o ponto: subtração por oposição.","palavraCritica":"subtração por oposição"},"comentario":{"resolucao":"CERTO. O saldo das contas é obtido pela oposição entre débitos e créditos (lado a lado, no razonete), e não por números negativos, que não eram aceitos na Europa quando o método se difundiu.","fundamento":"História da contabilidade; método das partidas dobradas.","macete":"Saldo = débitos versus créditos.","erroComum":"Estranhar a justificativa histórica.","comoBancaPensa":"Cobra curiosidade histórica."}},"CT-160":{"cognitivo":{"motivo":"Reconhecer o ponto: método digráfico.","palavraCritica":"digráfico"},"comentario":{"resolucao":"CERTO. Partidas dobradas também se chama método digráfico (dois registros), veneziano ou de Veneza.","fundamento":"Método das partidas dobradas.","macete":"Dobradas = digráfico = veneziano.","erroComum":"Não reconhecer o sinônimo.","comoBancaPensa":"Cobra sinônimo."}},"CT-161":{"cognitivo":{"motivo":"Reconhecer o ponto: livro caixa também usa partidas dobradas.","palavraCritica":"partidas simples"},"comentario":{"resolucao":"ERRADO. Na contabilidade, todos os registros seguem o método das partidas dobradas, inclusive os que alimentam o caixa e as contas a pagar. Partidas simples só aparecem em controles extracontábeis.","fundamento":"Método das partidas dobradas.","macete":"Contabilidade = partidas dobradas.","erroComum":"Achar que livros auxiliares usam partida simples.","comoBancaPensa":"Cria exceção."}},"CT-162":{"cognitivo":{"motivo":"Reconhecer o ponto: origem e aplicação dos recursos.","palavraCritica":"origem e da aplicação"},"comentario":{"resolucao":"CERTO. As partidas dobradas registram, em cada fato, a origem (crédito) e a aplicação (débito) dos recursos, o que justifica sua adoção universal.","fundamento":"Método das partidas dobradas.","macete":"Crédito = origem; débito = aplicação.","erroComum":"Inverter origem e aplicação.","comoBancaPensa":"Reproduz a lógica do método."}},"CT-163":{"cognitivo":{"motivo":"Reconhecer o ponto: débito aplicação, crédito origem.","palavraCritica":"lançamento a crédito"},"comentario":{"resolucao":"CERTO. Pelo método, cada fato implica lançamento a débito (aplicação dos recursos) e a crédito (origem dos recursos).","fundamento":"Método das partidas dobradas.","macete":"D = aplicação; C = origem.","erroComum":"Inverter.","comoBancaPensa":"Reproduz o conceito."}},"CT-164":{"cognitivo":{"motivo":"Reconhecer o ponto: método veneziano.","palavraCritica":"veneziano"},"comentario":{"resolucao":"CERTO. Pela origem histórica (mercadores de Veneza), o método das partidas dobradas também é chamado de veneziano.","fundamento":"História da contabilidade.","macete":"Veneza = partidas dobradas.","erroComum":"Não reconhecer o sinônimo.","comoBancaPensa":"Cobra sinônimo."}},"CT-165":{"cognitivo":{"motivo":"Reconhecer o ponto: não é 'uma conta para uma conta'.","palavraCritica":"para cada conta debitada, corresponde uma conta creditada"},"comentario":{"resolucao":"ERRADO. O método exige que o TOTAL dos débitos seja igual ao TOTAL dos créditos, não que cada conta debitada tenha exatamente uma conta creditada. Pode haver um débito e vários créditos, por exemplo (lançamentos de 2ª, 3ª e 4ª fórmulas).","fundamento":"Método das partidas dobradas; fórmulas de lançamento.","macete":"Iguala-se o valor total, não o número de contas.","erroComum":"Confundir valor com número de contas.","comoBancaPensa":"Troca soma de valores por correspondência de contas."}},"CT-166":{"cognitivo":{"motivo":"Reconhecer o ponto: lançamento devedor e credor de igual valor.","palavraCritica":"igual valor"},"comentario":{"resolucao":"CERTO, segundo a banca. A ideia central é que a cada débito corresponde crédito de igual valor, no conjunto do lançamento. A banca aceitou a formulação simplificada.","fundamento":"Método das partidas dobradas.","macete":"Débitos = créditos.","erroComum":"Confundir com a redação do item anterior.","comoBancaPensa":"Formulação simplificada aceita."}},"CT-167":{"cognitivo":{"motivo":"Reconhecer o ponto: registros por partidas dobradas.","palavraCritica":"partidas dobradas"},"comentario":{"resolucao":"CERTO. A escrituração contábil usa lançamentos pelo método das partidas dobradas.","fundamento":"Método das partidas dobradas.","macete":"Escrituração = partidas dobradas.","erroComum":"Desconfiar do óbvio.","comoBancaPensa":"Reproduz o conceito."}},"CT-168":{"cognitivo":{"motivo":"Reconhecer o ponto: vários créditos e um débito não é partida simples.","palavraCritica":"partida simples"},"comentario":{"resolucao":"ERRADO. Um débito para vários créditos com valores totais iguais é lançamento de 2ª fórmula (um débito, vários créditos) e continua sendo partida DOBRADA. Partida simples é o registro de uma só conta, sem contrapartida.","fundamento":"Fórmulas de lançamento; método das partidas dobradas.","macete":"Totais iguais = partidas dobradas.","erroComum":"Achar que 'menos débitos' é partida simples.","comoBancaPensa":"Troca o nome do método."}},"CT-169":{"cognitivo":{"motivo":"Reconhecer o ponto: terceira fórmula — vários débitos, um crédito.","palavraCritica":"terceira fórmula"},"comentario":{"resolucao":"CERTO. Terceira fórmula: dois ou mais débitos e um crédito. Débito em caixa e em juros passivos a transcorrer contra crédito em empréstimos é exatamente isso.","fundamento":"Fórmulas de lançamento.","macete":"1ª 1D/1C; 2ª 1D/vários C; 3ª vários D/1C; 4ª vários D/vários C.","erroComum":"Confundir 2ª e 3ª.","comoBancaPensa":"Cobra a contagem de débitos e créditos."}},"CT-170":{"cognitivo":{"motivo":"Reconhecer o ponto: depreciação — primeira fórmula.","palavraCritica":"primeira fórmula"},"comentario":{"resolucao":"CERTO. Reconhecer a depreciação: D despesa de depreciação, C depreciação acumulada. É um débito e um crédito, lançamento de primeira fórmula.","fundamento":"Fórmulas de lançamento; CPC 27.","macete":"Depreciação: 1D/1C.","erroComum":"Achar que envolve mais contas.","comoBancaPensa":"Cobra a fórmula."}},"CT-171":{"cognitivo":{"motivo":"Reconhecer o ponto: recebimento com juros — segunda fórmula.","palavraCritica":"terceira fórmula"},"comentario":{"resolucao":"ERRADO. Recebimento de 1.500 com 150 de juros e multa: D caixa 1.650; C clientes 1.500; C juros ativos 150. É um débito e dois créditos, lançamento de SEGUNDA fórmula.","fundamento":"Fórmulas de lançamento.","macete":"1 débito e 2 créditos = 2ª.","erroComum":"Contar ao contrário.","comoBancaPensa":"Troca a fórmula."}},"CT-172":{"cognitivo":{"motivo":"Reconhecer o ponto: 'Diversos a Diversos' — quarta fórmula.","palavraCritica":"segunda ou terceira fórmula"},"comentario":{"resolucao":"ERRADO. 'Diversos a Diversos' indica vários débitos e vários créditos, lançamento de QUARTA fórmula.","fundamento":"Fórmulas de lançamento (sistema clássico).","macete":"Diversos a Diversos = 4ª.","erroComum":"Confundir com 2ª e 3ª.","comoBancaPensa":"Troca a fórmula."}},"CT-173":{"cognitivo":{"motivo":"Reconhecer o ponto: baixa de título incobrável contra PECLD.","palavraCritica":"primeira fórmula"},"comentario":{"resolucao":"CERTO. A baixa de título incobrável já coberto pela perda estimada: D PECLD (retificadora do ativo), C clientes. É lançamento de 1ª fórmula, permutativo, sem efeito no PL, porque a perda já foi reconhecida na constituição da estimativa.","fundamento":"CPC 48; fórmulas de lançamento.","macete":"Baixa contra PECLD: permuta, sem despesa.","erroComum":"Achar que a baixa gera despesa.","comoBancaPensa":"Cobra fórmula e efeito."}},"CT-174":{"cognitivo":{"motivo":"Reconhecer o ponto: pagamento a fornecedor — permutativo.","palavraCritica":"permutativo"},"comentario":{"resolucao":"CERTO. D fornecedores (reduz passivo), C caixa (reduz ativo): ativo e passivo diminuem no mesmo valor, sem afetar o PL. É fato permutativo.","fundamento":"Doutrina contábil (fatos permutativos).","macete":"Não mexe no PL = permutativo.","erroComum":"Achar que redução de ativo é diminutiva.","comoBancaPensa":"Cobra o efeito no PL."}},"CT-175":{"cognitivo":{"motivo":"Reconhecer o ponto: financiamento de imobilizado — permutativo.","palavraCritica":"modificativo diminutivo"},"comentario":{"resolucao":"ERRADO. D imobilizado e D juros a transcorrer (retificadora do passivo) contra C financiamentos: só contas patrimoniais. Juros a transcorrer não é conta de resultado, logo o fato é permutativo. Os juros só viram despesa com o tempo.","fundamento":"Doutrina contábil (fatos permutativos); CPC 12.","macete":"Juros a transcorrer: passivo, não resultado.","erroComum":"Tomar juros a transcorrer por despesa.","comoBancaPensa":"Confunde retificadora com resultado."}},"CT-176":{"cognitivo":{"motivo":"Reconhecer o ponto: aumento simultâneo de ativo e passivo é permutativo.","palavraCritica":"não caracteriza fato permutativo"},"comentario":{"resolucao":"ERRADO. A primeira parte está certa, mas a troca que aumenta ativo e passivo no mesmo valor, como a compra a prazo, TAMBÉM é fato permutativo, porque não altera o PL.","fundamento":"Doutrina contábil (fatos permutativos).","macete":"Permutativo = PL intocado.","erroComum":"Achar que mudar o total do ativo altera o PL.","comoBancaPensa":"Primeira parte certa, segunda errada."}},"CT-177":{"cognitivo":{"motivo":"Reconhecer o ponto: movimentação ativo–passivo não é modificativa.","palavraCritica":"fato modificativo"},"comentario":{"resolucao":"ERRADO. Movimentação entre contas do ativo e do passivo, sem conta de resultado, não altera o PL. É fato permutativo, e não modificativo.","fundamento":"Doutrina contábil (fatos contábeis).","macete":"Modificativo exige efeito no PL.","erroComum":"Confundir estrutura patrimonial com PL.","comoBancaPensa":"Troca o tipo do fato."}},"CT-178":{"cognitivo":{"motivo":"Reconhecer o ponto: retenções sobre salários — permuta entre passivos.","palavraCritica":"permutativos entre elementos passivos"},"comentario":{"resolucao":"CERTO. Ao reter, por exemplo, IRRF ou INSS do empregado: D salários a pagar, C IRRF/INSS a recolher. Um passivo diminui e outro aumenta, num fato permutativo entre passivos.","fundamento":"Doutrina contábil; contabilização da folha.","macete":"Retenção = troca de credor.","erroComum":"Achar que a retenção é despesa.","comoBancaPensa":"Cobra o efeito da retenção."}},"CT-179":{"cognitivo":{"motivo":"Reconhecer o ponto: desconto de duplicatas — fato permutativo.","palavraCritica":"permutativo"},"comentario":{"resolucao":"CERTO. No desconto: D bancos (95), D encargos a transcorrer (5, retificadora do passivo), C duplicatas descontadas (100). Só contas patrimoniais, logo fato permutativo. Os encargos viram despesa com o tempo.","fundamento":"CPC 48; doutrina (duplicatas descontadas).","macete":"Desconto de duplicata = empréstimo = permuta.","erroComum":"Lançar os encargos direto como despesa.","comoBancaPensa":"Cobra a natureza do desconto."}},"CT-180":{"cognitivo":{"motivo":"Reconhecer o ponto: financiamento recebido — permutativo.","palavraCritica":"modificativo"},"comentario":{"resolucao":"ERRADO. O financiamento com entrada imediata do recurso aumenta o ativo (caixa) e o passivo (financiamento) no mesmo valor, o que é fato permutativo. Na questão original, o fato modificativo era o recebimento de bem em doação, que aumenta o PL.","fundamento":"Doutrina contábil (fatos contábeis).","macete":"Doação recebida = modificativo; financiamento = permutativo.","erroComum":"Achar que entrada de dinheiro é sempre receita.","comoBancaPensa":"Troca a classificação."}}});
